INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C1','kor',1,2,'u5',1,'모양이 비슷한 글자 찾고 다른 자리 알기 — 책 제목에서 하나만 다른 글자 찾기(금·음 / 재·해 / 람·란 / 파·나), 첫 자음자·모음자·받침 가운데 어느 자리가 다른지 말하기, 글자가 달라지면 소리와 뜻도 달라짐',ARRAY['2국04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C2','kor',1,2,'u5',3,'한글을 만든 원리와 까닭 알기 — 자음자는 획을 더하면 소리가 세짐(ㄱ→ㅋ · ㄷ→ㅌ · ㅈ→ㅊ), 모음자는 방향을 달리하거나 획을 더함(ㅗ→ㅏ·ㅜ·ㅓ · ㅏ→ㅑ), 한자를 빌려 쓰던 백성의 불편, 세종 대왕·조선 시대·백성이 쉽게 읽고 쓰게 하려고, 한글 덕분에 좋은 점',ARRAY['2국04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C3','kor',1,2,'u5',4,'글자를 바꾸어 뜻이 다른 낱말 만들기 — 달→발→별→벽, 「볼」·「감」·「솔」의 첫 자음자·모음자·받침 가운데 하나만 바꾸기, 하나만 달라져도 모양·소리·뜻이 다른 새 낱말, 뜻이 있는 낱말만 만들기',ARRAY['2국04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C4','kor',1,2,'u5',6,'책에 흥미 가지기 — 「그래, 책이야!」 내용 알기(동키·몽키·노트북과 책), 재미있었던 부분 나누기, 재미는 웃음만이 아니라 감동·놀라움·새로 안 것, 「책은 ○○이다」 까닭과 함께 말하기, 제목과 고른 까닭으로 책 추천하기',ARRAY['2국02-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C5','kor',1,2,'u5',8,'글쓴이에게 있었던 일과 마음 알기 — 「너무너무 어려운 훌라후프 돌리기」에서 있었던 일을 차례대로 정리하고, 일에 따라 달라지는 글쓴이의 마음(하기 싫은·부러운·뿌듯한) 짐작하기',ARRAY['2국05-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C6','kor',1,2,'u5',8,'생각이나 느낌을 구체적으로 나누기 — 글쓴이가 한 일과 마음에 대한 내 생각·느낌을 「좋았다」로 끝내지 않고 글의 어느 부분 때문인지 넣어 말하기, 글쓴이의 말을 그대로 옮기지 않기, 마음이 비슷한 내 경험 떠올리기, 안내판을 읽고 떠오른 생각 말하기',ARRAY['2국05-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C7','kor',1,2,'u5',10,'독서 계획 세우고 책 활동 하기 — 독서 계단 맨 아래 칸부터 읽고 싶은 차례대로 쓰기, 흥미와 읽기 수준에 맞는 책, 한 권을 끝까지 읽고 색칠하기, 책 보물 찾기·책 카페 놀이',ARRAY['2국02-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C8','kor',1,2,'u5',12,'물건을 셀 때 쓰는 말 알기 — 종이 한 장 · 연필 한 자루 · 차 한 대 · 신발 한 켤레 · 수박 한 통 · 수저 한 벌, 배추 한 포기 · 배 한 척 · 쌀 한 톨 · 집 한 채 · 두부 한 모(기초 다지기)',ARRAY['2국04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X01','kor',1,'u5',ARRAY['K1-2-u5-C1','K1-2-u5-C3']::text[],'첫 자음자·모음자·받침 자리를 헷갈려 다른 자리를 바꾸거나 다른 자리 이름을 말한다 (「람」·「란」을 모음자가 다르다고 하기)','글자를 손가락으로 짚으며 「첫 자음자 → 모음자 → 받침」 차례로 자리 이름을 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X02','kor',1,'u5',ARRAY['K1-2-u5-C1','K1-2-u5-C3']::text[],'똑같은 글자를 「비슷한 글자」로 고르거나, 두 자리 이상 다른 글자를 「하나만 다르다」고 한다 (달 → 별)','두 글자를 세 칸에 나란히 적고 다른 칸에 동그라미 — 동그라미가 하나일 때만 비슷한 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X03','kor',1,'u5',ARRAY['K1-2-u5-C1','K1-2-u5-C3']::text[],'글자가 하나만 달라지면 소리나 뜻은 그대로라고 여긴다','「금」과 「음」을 소리 내어 읽고 뜻을 말해 보게 하기 — 하나만 달라도 다른 낱말이 된다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X04','kor',1,'u5',ARRAY['K1-2-u5-C2']::text[],'한글은 누가·언제·왜 만들었는지 알 수 없다거나 저절로 생겼다고 여긴다','「세종 대왕 · 조선 시대 · 백성」 세 낱말 카드로 누가·언제·왜를 짝지어 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X05','kor',1,'u5',ARRAY['K1-2-u5-C2']::text[],'한글을 만든 까닭이나 한글이 있어 좋은 점을 백성(누구나)의 삶이 아닌 것에서 찾는다','「한글이 없던 때 백성은 무엇이 불편했을까?」 물은 뒤, 지금 우리가 책을 읽고 편지를 쓰는 것과 견주어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X06','kor',1,'u5',ARRAY['K1-2-u5-C2']::text[],'획을 더하면 소리가 세진다는 원리나 모음자의 방향 원리를 모른다 (ㄱ보다 ㅋ이 약하다고 하기)','「ㄱ」과 「ㅋ」을 손바닥 앞에서 소리 내어 바람 세기를 느껴 보고, 「ㅗ」 카드를 돌려 ㅏ·ㅜ·ㅓ를 만들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X07','kor',1,'u5',ARRAY['K1-2-u5-C3']::text[],'소리는 나지만 뜻이 없는 글자(곺·솝)를 낱말이라고 한다','「그게 무엇인지 그림으로 그릴 수 있나요?」 — 그릴 수도 설명할 수도 없으면 낱말이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X08','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C7']::text[],'책을 두께·값·무게·표지 색처럼 내용과 상관없는 것으로 고른다','「그걸 알면 무슨 이야기인지 알 수 있나요?」 — 제목을 보고 내용을 짐작해 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X09','kor',1,'u5',ARRAY['K1-2-u5-C4']::text[],'재미있는 책은 웃긴 이야기뿐이라고 여긴다 (감동·놀라움·새로 안 것은 재미가 아니라고 보기)','「웃음 · 감동 · 놀라움 · 새로 앎」 네 칸에 읽은 책을 하나씩 넣어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X10','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C6']::text[],'「재미있었다」·「좋았다」 한마디로 끝내고 어느 부분이 왜 그런지 말하지 않는다','「어느 부분이? 왜?」 두 물음에 하나씩 답하게 하기 — 「~ 부분이 ~해서」 틀 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X11','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C6']::text[],'재미있게 느낀 부분이나 생각이 나와 다른 친구를 틀렸다고 한다','「사람마다 마음이 움직이는 곳이 달라요」 — 친구에게 왜 그 부분인지 물어보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X12','kor',1,'u5',ARRAY['K1-2-u5-C4']::text[],'전자 기기는 나쁘고 책만 옳다는 식으로 하나를 나쁘다고 정한다','「나쁜 것 찾기」 대신 「책이 주는 재미」 한 가지 말하기 — 동키가 왜 책에 빠졌을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X13','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C5']::text[],'글에 없는 일을 넣거나, 인물이 한 일을 바꾸거나, 있었던 일의 차례를 뒤집는다','「그 일이 글 몇째 줄에 있나요?」 손가락으로 짚게 하고, 차례는 처음·그다음·마지막으로 줄 세우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X14','kor',1,'u5',ARRAY['K1-2-u5-C5']::text[],'있었던 일과 마음을 잇지 못하거나 마음을 거꾸로 짐작한다 (「어휴.」를 신난 마음으로 읽기)','「나라면 그때 어떤 마음일까?」 — 「어휴.」·「우아!」를 소리 내어 견주어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X15','kor',1,'u5',ARRAY['K1-2-u5-C6']::text[],'글쓴이가 쓴 문장을 그대로 옮기거나 글쓴이가 한 일과 상관없는 말을 생각이나 느낌이라고 한다','「그건 글에 있는 말이에요. 그 부분을 읽고 네 마음은 어땠어?」 — 글쓴이가 한 일을 먼저 짚게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X16','kor',1,'u5',ARRAY['K1-2-u5-C6']::text[],'하는 일이나 물건이 같아야만 비슷한 경험이라고 여긴다','「무슨 일이 있었고 그때 마음이 어땠나?」 두 칸을 글과 내 경험에 나란히 채워 마음이 닮았는지 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X17','kor',1,'u5',ARRAY['K1-2-u5-C7']::text[],'독서 계단의 차례를 거꾸로 쓰거나(가장 높은 칸이 먼저) 다 읽기 전에 색칠한다','종이 계단을 아래에서 위로 손가락으로 오르며 「첫째 → 둘째」 소리 내기, 색칠은 다 읽은 칸만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X18','kor',1,'u5',ARRAY['K1-2-u5-C7']::text[],'책 활동을 쪽지·선물·권수를 모으는 겨루기로 여긴다','「보물 쪽지의 질문에 답하려면 무엇을 해야 하지?」 — 진짜 보물은 책을 읽는 것이라고 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X19','kor',1,'u5',ARRAY['K1-2-u5-C7']::text[],'한 권을 끝까지 읽지 않고 훑어 읽거나 뛰어 읽고, 읽기 어려운 책부터 골라 끝까지 읽어 내지 못한다','첫 계단엔 읽기 쉽고 흥미 있는 책 — 「한 권 끝까지 → 색칠 → 다음 칸」 고리를 보여 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X20','kor',1,'u5',ARRAY['K1-2-u5-C8']::text[],'물건에 맞지 않는 세는 말을 쓰거나 무엇이든 「개」로 센다 (신발 한 대·종이 한 자루)','물건 그림 카드와 세는 말 카드를 짝지어 「종이 한 장 · 연필 한 자루」 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#1','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','『국어』 148쪽 — 「채」와 「재」를 소리 내어 읽을 때 소리가 더 세게 나는 글자는?',ARRAY['K1-2-u5-X06','K1-2-u5-X03']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 148쪽 — 「채」와 「재」를 소리 내어 읽을 때 소리가 더 세게 나는 글자는?","options":[{"t":"채","correct":true},{"t":"재","mis":"K1-2-u5-X06"},{"t":"두 글자의 소리 세기가 똑같아요","mis":"K1-2-u5-X03"}],"explanation":["소리 내어 읽어 보면 「채」가 「재」보다 더 세게 나요.","「ㅊ」은 「ㅈ」에 획을 더한 자음자예요.","손바닥을 입 앞에 대고 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#2','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','『국어』 148쪽 — 「금도끼」의 「금」과 모양이 비슷한 글자는?',ARRAY['K1-2-u5-X02']::text[],false,'{"seq":2,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 148쪽 — 「금도끼」의 「금」과 모양이 비슷한 글자는?","options":[{"t":"「웃음」의 「음」","correct":true},{"t":"「금도끼」의 「금」","mis":"K1-2-u5-X02"},{"t":"「부채」의 「부」","mis":"K1-2-u5-X02"}],"explanation":["「금」과 「음」은 첫 자음자만 달라요.","똑같은 글자는 비슷한 글자가 아니에요.","하나만 다른 글자를 찾아요."],"asset":{"type":"passage","lines":["재주 많은 다섯 친구","빨간 부채 파란 부채","웃음은 힘이 세다","젊어지는 샘물","금도끼 은도끼","요술 항아리","가나다 글자 놀이","바람과 해님"],"title":"『국어』 148쪽 — 책 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#3','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','『국어』 148쪽 — 「바람과 해님」의 「람」과 모양이 비슷한 글자는?',ARRAY['K1-2-u5-X02']::text[],false,'{"seq":3,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 148쪽 — 「바람과 해님」의 「람」과 모양이 비슷한 글자는?","options":[{"t":"「파란 부채」의 「란」","correct":true},{"t":"「바람」의 「바」","mis":"K1-2-u5-X02"},{"t":"「바람」의 「람」","mis":"K1-2-u5-X02"}],"explanation":["「람」과 「란」은 받침만 달라요.","「바」는 여러 자리가 달라요.","책 제목을 다시 읽어 봐요."],"asset":{"type":"passage","lines":["재주 많은 다섯 친구","빨간 부채 파란 부채","웃음은 힘이 세다","젊어지는 샘물","금도끼 은도끼","요술 항아리","가나다 글자 놀이","바람과 해님"],"title":"『국어』 148쪽 — 책 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#4','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','『국어』 148쪽 — 「재주」의 「재」와 모양이 비슷한 글자는?',ARRAY['K1-2-u5-X02']::text[],false,'{"seq":4,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 148쪽 — 「재주」의 「재」와 모양이 비슷한 글자는?","options":[{"t":"「해님」의 「해」","correct":true},{"t":"「재주」의 「주」","mis":"K1-2-u5-X02"},{"t":"「다섯」의 「섯」","mis":"K1-2-u5-X02"}],"explanation":["「재」와 「해」는 자음자만 달라요.","「주」와 「섯」은 여러 자리가 달라요.","모음자가 같은 글자를 찾아요."],"asset":{"type":"passage","lines":["재주 많은 다섯 친구","빨간 부채 파란 부채","웃음은 힘이 세다","젊어지는 샘물","금도끼 은도끼","요술 항아리","가나다 글자 놀이","바람과 해님"],"title":"『국어』 148쪽 — 책 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#5','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'match','auto','『국어』 148쪽 2번 — 모양이 비슷한 글자끼리 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u5-C1","difficulty":2,"kind":"match","stem":"『국어』 148쪽 2번 — 모양이 비슷한 글자끼리 이어 보세요.","pairs":[{"l":"금","r":"음"},{"l":"재","r":"해"},{"l":"람","r":"란"},{"l":"파","r":"나"}],"mis":"K1-2-u5-X02","explanation":["금·음, 재·해, 람·란, 파·나예요.","두 글자는 한 자리만 달라요.","148쪽 책 제목에서 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#6','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'mc','auto','『국어』 149쪽 3번 — 「금」과 「음」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":6,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"『국어』 149쪽 3번 — 「금」과 「음」은 어느 자리가 다른가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["「ㄱ」과 「ㅇ」, 첫 자음자만 달라요.","모음자 「ㅡ」와 받침 「ㅁ」은 같아요.","글자를 세 자리로 나누어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#7','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'mc','auto','『국어』 149쪽 3번 — 「람」과 「란」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":7,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"『국어』 149쪽 3번 — 「람」과 「란」은 어느 자리가 다른가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㅁ」과 「ㄴ」이 달라요.","첫 자음자 「ㄹ」과 모음자 「ㅏ」는 같아요.","글자 아래쪽을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#8','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'mc','auto','「파」와 「나」는 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":8,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"「파」와 「나」는 어느 자리가 다른가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["「ㅍ」과 「ㄴ」, 첫 자음자가 달라요.","두 글자 모두 받침이 없어요.","모음자 「ㅏ」는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#9','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'ox','auto','『국어』 149쪽 — 글자가 하나만 달라져도 소리와 뜻이 달라져요.',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":9,"concept":"K1-2-u5-C1","difficulty":2,"kind":"ox","stem":"『국어』 149쪽 — 글자가 하나만 달라져도 소리와 뜻이 달라져요.","answer":"O","reason_options":[{"t":"「금」과 「음」처럼 한 자리만 달라도 다른 글자가 되니까","correct":true},{"t":"모양이 비슷하면 소리와 뜻도 같으니까","mis":"K1-2-u5-X03"}],"mis":"K1-2-u5-X03","explanation":["글자가 달라지면 소리와 뜻도 달라져요.","「금」과 「음」은 소리도 뜻도 달라요.","149쪽 3번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#10','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C4',3,'mc','auto','『국어』 149쪽 4번 — 읽고 싶은 책을 고를 때 먼저 할 일은?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":10,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"『국어』 149쪽 4번 — 읽고 싶은 책을 고를 때 먼저 할 일은?","options":[{"t":"제목을 살펴보고 어떤 내용일지 짐작해요","correct":true},{"t":"가장 두꺼운 책을 골라요","mis":"K1-2-u5-X08"},{"t":"표지 색깔만 보고 골라요","mis":"K1-2-u5-X08"}],"explanation":["제목을 보면 어떤 이야기일지 짐작할 수 있어요.","두께나 색깔로는 내용을 알 수 없어요.","149쪽 4번이에요."],"asset":{"type":"passage","lines":["재주 많은 다섯 친구","빨간 부채 파란 부채","웃음은 힘이 세다","젊어지는 샘물","금도끼 은도끼","요술 항아리","가나다 글자 놀이","바람과 해님"],"title":"『국어』 148쪽 — 책 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
