INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#3','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'error','auto','친구가 「금」과 모양이 비슷한 글자로 「금도끼」의 「금」을 골랐어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X02']::text[],false,'{"seq":3,"concept":"K1-2-u5-C1","difficulty":3,"kind":"error","stem":"친구가 「금」과 모양이 비슷한 글자로 「금도끼」의 「금」을 골랐어요. 무엇이 잘못되었나요?","options":[{"t":"똑같은 글자예요 — 하나만 다른 비슷한 글자를 찾아요","correct":true,"mis_target":"K1-2-u5-X02"},{"t":"잘 골랐어요","mis":"K1-2-u5-X02"},{"t":"「도」를 골라야 해요","mis":"K1-2-u5-X02"}],"explanation":["똑같은 글자는 비슷한 글자가 아니에요.","「음」처럼 하나만 다른 글자를 찾아요.","148쪽 2번이에요."],"asset":{"type":"passage","lines":["재주 많은 다섯 친구","빨간 부채 파란 부채","웃음은 힘이 세다","젊어지는 샘물","금도끼 은도끼","요술 항아리","가나다 글자 놀이","바람과 해님"],"title":"『국어』 148쪽 — 책 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#4','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'error','auto','「람」과 「란」은 모음자가 다르다고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C1","difficulty":3,"kind":"error","stem":"「람」과 「란」은 모음자가 다르다고 했어요. 무엇이 잘못되었나요?","options":[{"t":"받침 「ㅁ」과 「ㄴ」이 달라요","correct":true,"mis_target":"K1-2-u5-X01"},{"t":"맞게 말했어요","mis":"K1-2-u5-X01"},{"t":"첫 자음자가 달라요","mis":"K1-2-u5-X01"}],"explanation":["두 글자의 모음자는 똑같이 「ㅏ」예요.","다른 것은 받침이에요.","자리 이름을 짚어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#5','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'mc','auto','「금」과 「곰」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":5,"concept":"K1-2-u5-C1","difficulty":3,"kind":"mc","stem":"「금」과 「곰」은 어느 자리가 다른가요?","options":[{"t":"모음자","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["「ㅡ」와 「ㅗ」, 모음자가 달라요.","첫 자음자 「ㄱ」과 받침 「ㅁ」은 같아요.","가운데 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#6','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'mc','auto','「채」와 「재」 가운데 소리가 더 센 「채」의 자음자는?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":6,"concept":"K1-2-u5-C1","difficulty":3,"kind":"mc","stem":"「채」와 「재」 가운데 소리가 더 센 「채」의 자음자는?","options":[{"t":"ㅊ","correct":true},{"t":"ㅈ","mis":"K1-2-u5-X06"},{"t":"ㅎ","mis":"K1-2-u5-X06"}],"explanation":["「채」의 자음자는 「ㅊ」이에요.","「ㅊ」은 「ㅈ」에 획을 더해 소리가 세요.","150쪽에서 더 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#7','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'ox','auto','「재」와 「해」는 받침이 달라서 다른 글자예요.',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":7,"concept":"K1-2-u5-C1","difficulty":3,"kind":"ox","stem":"「재」와 「해」는 받침이 달라서 다른 글자예요.","answer":"X","reason_options":[{"t":"두 글자는 받침이 없고 자음자 「ㅈ」과 「ㅎ」이 다르니까","correct":true},{"t":"두 글자 모두 받침이 있으니까","mis":"K1-2-u5-X01"}],"mis":"K1-2-u5-X01","explanation":["「재」와 「해」에는 받침이 없어요.","다른 것은 자음자예요.","글자 아래쪽을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#8','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',4,'sa','auto','「금」에서 첫 자음자 「ㄱ」을 「ㅇ」으로 바꾸면 어떤 글자가 되나요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C1","difficulty":4,"kind":"sa","stem":"「금」에서 첫 자음자 「ㄱ」을 「ㅇ」으로 바꾸면 어떤 글자가 되나요?","answer":["음"],"explanation":["「ㅇ」+「ㅡ」+「ㅁ」은 「음」이에요.","「웃음」의 「음」과 같아요.","148쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#9','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',4,'essay','teacher','「람」과 「란」을 견주어 같은 점과 다른 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C1","difficulty":4,"kind":"essay","stem":"「람」과 「란」을 견주어 같은 점과 다른 점을 쓰세요.","answer_guide":{"answer":"예: 첫 자음자 「ㄹ」과 모음자 「ㅏ」는 같고, 받침이 「ㅁ」과 「ㄴ」으로 달라요. — 같은 자리와 다른 자리를 바르게 말하면 맞아요.","scoring_points":["같은 자리를 바르게 썼는가","다른 자리(받침)를 바르게 썼는가","자리 이름을 바르게 썼는가"]},"explanation":["세 자리로 나누어 견주어요.","받침만 달라요.","149쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#10','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C4',4,'essay','teacher','『국어』 148쪽 책 제목 가운데 읽고 싶은 책을 하나 골라 제목을 쓰고, 어떤 내용일지 짐작해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"『국어』 148쪽 책 제목 가운데 읽고 싶은 책을 하나 골라 제목을 쓰고, 어떤 내용일지 짐작해 쓰세요.","answer_guide":{"answer":"예: 「바람과 해님」 — 바람과 해님이 누가 더 힘이 센지 겨루는 이야기일 것 같아요. — 제목과 짐작한 내용이 있으면 맞아요.","scoring_points":["책 제목을 썼는가","제목을 보고 내용을 짐작했는가","문장이 자연스러운가"]},"explanation":["먼저 제목을 살펴봐요.","어떤 이야기일지 짐작해 봐요.","149쪽 4번이에요."],"asset":{"type":"passage","lines":["재주 많은 다섯 친구","빨간 부채 파란 부채","웃음은 힘이 세다","젊어지는 샘물","금도끼 은도끼","요술 항아리","가나다 글자 놀이","바람과 해님"],"title":"『국어』 148쪽 — 책 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#1','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','『국어』 150쪽 1번 — 「ㄱ」에 한 획을 더하면 어떤 자음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":1,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 150쪽 1번 — 「ㄱ」에 한 획을 더하면 어떤 자음자가 되나요?","options":[{"t":"ㅋ","correct":true},{"t":"ㄴ","mis":"K1-2-u5-X06"},{"t":"ㄷ","mis":"K1-2-u5-X06"}],"explanation":["「ㄱ」에 획을 더하면 「ㅋ」이에요.","소리도 더 세져요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
