INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#3','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','「ㅈ」에 한 획을 더하면 어떤 자음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"「ㅈ」에 한 획을 더하면 어떤 자음자가 되나요?","options":[{"t":"ㅊ","correct":true},{"t":"ㅅ","mis":"K1-2-u5-X06"},{"t":"ㅎ","mis":"K1-2-u5-X06"}],"explanation":["「ㅈ」에 획을 더하면 「ㅊ」이에요.","「채」가 「재」보다 센 까닭이에요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#4','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','한글을 만든 사람은 누구인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":4,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글을 만든 사람은 누구인가요?","options":[{"t":"세종 대왕","correct":true},{"t":"이순신 장군","mis":"K1-2-u5-X04"},{"t":"아무도 몰라요","mis":"K1-2-u5-X04"}],"explanation":["세종 대왕이 백성을 위해 만들었어요.","누가 만들었는지 알려진 글자예요.","150쪽 2번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
