INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#6','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','자음자에 획을 더하면 소리는 어떻게 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":6,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"자음자에 획을 더하면 소리는 어떻게 되나요?","options":[{"t":"더 세져요","correct":true},{"t":"더 약해져요","mis":"K1-2-u5-X06"},{"t":"똑같아요","mis":"K1-2-u5-X06"}],"explanation":["「ㄱ」보다 「ㅋ」의 소리가 더 세요.","차례로 소리 내어 읽어 봐요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#7','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','「ㅗ」를 거꾸로 뒤집으면 어떤 모음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":7,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㅗ」를 거꾸로 뒤집으면 어떤 모음자가 되나요?","options":[{"t":"ㅜ","correct":true},{"t":"ㅏ","mis":"K1-2-u5-X06"},{"t":"ㅡ","mis":"K1-2-u5-X06"}],"explanation":["「ㅗ」의 방향을 아래로 바꾸면 「ㅜ」예요.","모음자는 방향을 달리하면 다른 글자가 돼요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#8','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','한글이 만들어지기 전에는 어떤 글자를 빌려 썼나요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":8,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"한글이 만들어지기 전에는 어떤 글자를 빌려 썼나요?","options":[{"t":"중국의 글자인 한자","correct":true},{"t":"영어 알파벳","mis":"K1-2-u5-X04"},{"t":"그림 글자","mis":"K1-2-u5-X04"}],"explanation":["우리 글자가 없어서 한자를 빌려 썼어요.","한자는 배우기 어려웠어요.","이야기 첫째 줄이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#9','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','『국어』 151쪽 3번 — 한자로만 글을 썼을 때 어떤 문제가 있었나요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":9,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"『국어』 151쪽 3번 — 한자로만 글을 썼을 때 어떤 문제가 있었나요?","options":[{"t":"배우기 어려워서 많은 백성이 글을 읽지 못했어요","correct":true},{"t":"글자가 너무 쉬워서 재미가 없었어요","mis":"K1-2-u5-X05"},{"t":"누구나 글을 잘 읽었어요","mis":"K1-2-u5-X05"}],"explanation":["한자는 배우기 어려웠어요.","그래서 많은 백성이 글을 읽지 못했어요.","이야기 둘째 줄이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#10','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',3,'mc','auto','세종 대왕이 한글을 만든 까닭은?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"세종 대왕이 한글을 만든 까닭은?","options":[{"t":"백성이 쉽게 읽고 쓸 수 있게 하려고","correct":true},{"t":"임금만 몰래 쓰려고","mis":"K1-2-u5-X05"},{"t":"한자보다 더 어렵게 하려고","mis":"K1-2-u5-X05"}],"explanation":["백성이 글을 읽지 못하는 것을 안타깝게 여겼어요.","누구나 쉽게 읽고 쓰게 하려고 만들었어요.","151쪽 4번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
