INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#8','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',4,'sa','auto','「ㄷ」에 한 획을 더하면 어떤 자음자가 되나요? 자음자 하나를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C2","difficulty":4,"kind":"sa","stem":"「ㄷ」에 한 획을 더하면 어떤 자음자가 되나요? 자음자 하나를 쓰세요.","answer":["ㅌ"],"explanation":["「ㄷ」에 획을 더하면 「ㅌ」이에요.","소리도 더 세져요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#9','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',4,'essay','teacher','『국어』 151쪽 5번 — 한글이 있어 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C2","difficulty":4,"kind":"essay","stem":"『국어』 151쪽 5번 — 한글이 있어 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 내 생각을 자유롭게 글로 쓸 수 있다. / 책을 읽을 수 있다. / 멀리 있는 사람에게 편지를 쓸 수 있다. — 두 가지면 맞아요.","scoring_points":["좋은 점을 두 가지 썼는가","한글 덕분에 할 수 있는 일인가","문장이 자연스러운가"]},"explanation":["한글 덕분에 우리가 할 수 있는 일을 떠올려요.","생각 쓰기·책 읽기·편지 쓰기가 있어요.","151쪽 5번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#10','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',4,'essay','teacher','한글이 없어서 한자만 써야 한다면 우리 생활은 어떨지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":4,"kind":"essay","stem":"한글이 없어서 한자만 써야 한다면 우리 생활은 어떨지 쓰세요.","answer_guide":{"answer":"예: 한자를 몰라서 책을 읽지 못하고 친구에게 편지도 쓰기 어려웠을 거예요. — 읽고 쓰기의 불편이 드러나면 맞아요.","scoring_points":["읽거나 쓰기의 불편을 썼는가","한자가 어렵다는 점과 이었는가","문장이 자연스러운가"]},"explanation":["옛날 백성이 겪은 불편을 떠올려요.","그래서 한글이 소중해요.","151쪽 3번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#1','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',1,'mc','auto','『국어』 152쪽 1번 — 「달」의 첫 자음자를 「ㅂ」으로 바꾸면?',ARRAY['K1-2-u5-X02']::text[],false,'{"seq":1,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 152쪽 1번 — 「달」의 첫 자음자를 「ㅂ」으로 바꾸면?","options":[{"t":"발","correct":true},{"t":"별","mis":"K1-2-u5-X02"},{"t":"밭","mis":"K1-2-u5-X02"}],"explanation":["「ㄷ」을 「ㅂ」으로 바꾸면 「발」이에요.","「별」과 「밭」은 두 자리가 바뀌었어요.","첫 자음자만 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
