INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#8','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',2,'mc','auto','「달 → 발 → 별 → 벽」에서 「별」을 「벽」으로 바꿀 때 바꾼 자리는?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":8,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「달 → 발 → 별 → 벽」에서 「별」을 「벽」으로 바꿀 때 바꾼 자리는?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㄹ」이 「ㄱ」으로 바뀌었어요.","첫 자음자와 모음자는 그대로예요.","152~153쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#9','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',2,'ox','auto','글자 가운데 하나만 바꾸어도 뜻이 다른 낱말이 될 수 있어요.',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"글자 가운데 하나만 바꾸어도 뜻이 다른 낱말이 될 수 있어요.","answer":"O","reason_options":[{"t":"「달」과 「발」처럼 한 자리만 달라도 뜻이 다르니까","correct":true},{"t":"하나만 바꾸면 뜻은 그대로니까","mis":"K1-2-u5-X03"}],"mis":"K1-2-u5-X03","explanation":["하나만 달라져도 모양·소리·뜻이 다른 낱말이 돼요.","이것이 한글의 특징이에요.","153쪽 지식 발견하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#10','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',3,'mc','auto','『국어활동』 58~59쪽 — 「솔」에서 받침만 바꾸어 만든 뜻이 있는 낱말은?',ARRAY['K1-2-u5-X07','K1-2-u5-X01']::text[],false,'{"seq":10,"concept":"K1-2-u5-C3","difficulty":3,"kind":"mc","stem":"『국어활동』 58~59쪽 — 「솔」에서 받침만 바꾸어 만든 뜻이 있는 낱말은?","options":[{"t":"손","correct":true},{"t":"솝","mis":"K1-2-u5-X07"},{"t":"실","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㄹ」을 「ㄴ」으로 바꾸면 「손」이에요.","「솝」은 뜻이 없는 글자예요.","뜻이 있는 낱말만 만들어요."],"asset":{"type":"scene","icon":"🌲➡️🧩","text":"「솔」에서 길을 따라 낱말 만들기 — 『국어활동』 58~59쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#1','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',2,'mc','auto','「감」의 첫 자음자만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「감」의 첫 자음자만 바꾼 낱말은?","options":[{"t":"밤","correct":true},{"t":"곰","mis":"K1-2-u5-X01"},{"t":"갓","mis":"K1-2-u5-X01"}],"explanation":["「ㄱ」을 「ㅂ」으로 바꾸면 「밤」이에요.","「곰」은 모음자, 「갓」은 받침을 바꿨어요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#2','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',2,'blank','auto','빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#3','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'error','auto','친구가 「볼」의 첫 자음자만 바꾸어 「봄」을 만들었다고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":3,"kind":"error","stem":"친구가 「볼」의 첫 자음자만 바꾸어 「봄」을 만들었다고 했어요. 무엇이 잘못되었나요?","options":[{"t":"「봄」은 받침을 바꾼 낱말이에요 — 첫 자음자를 바꾸면 「돌」, 「솔」이에요","correct":true,"mis_target":"K1-2-u5-X01"},{"t":"잘 만들었어요","mis":"K1-2-u5-X01"},{"t":"「봄」은 모음자를 바꾼 낱말이에요","mis":"K1-2-u5-X01"}],"explanation":["「ㄹ」이 「ㅁ」으로 바뀌었으니 받침이에요.","첫 자음자를 바꾸면 「돌」, 「솔」이에요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#4','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'error','auto','친구가 「곰」의 받침을 바꾸어 「곺」을 만들었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X07','K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C3","difficulty":3,"kind":"error","stem":"친구가 「곰」의 받침을 바꾸어 「곺」을 만들었어요. 무엇이 잘못되었나요?","options":[{"t":"「곺」은 뜻이 없는 글자예요 — 「공」, 「곳」처럼 뜻이 있는 낱말을 만들어요","correct":true,"mis_target":"K1-2-u5-X07"},{"t":"잘 만들었어요","mis":"K1-2-u5-X07"},{"t":"받침은 바꿀 수 없어요","mis":"K1-2-u5-X01"}],"explanation":["소리만 나고 뜻이 없으면 낱말이 아니에요.","뜻이 있는 낱말만 만들어요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#5','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'error','auto','친구가 「달」에서 「별」을 만들고 「한 자리만 바꾸었어요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X02','K1-2-u5-X01']::text[],false,'{"seq":5,"concept":"K1-2-u5-C3","difficulty":3,"kind":"error","stem":"친구가 「달」에서 「별」을 만들고 「한 자리만 바꾸었어요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"첫 자음자와 모음자, 두 자리를 바꾸었어요","correct":true,"mis_target":"K1-2-u5-X02"},{"t":"맞게 말했어요","mis":"K1-2-u5-X02"},{"t":"받침을 바꾸었어요","mis":"K1-2-u5-X01"}],"explanation":["「ㄷ」→「ㅂ」, 「ㅏ」→「ㅕ」 두 자리가 바뀌었어요.","한 자리씩 바꾸면 달 → 발 → 별이에요.","152~153쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#6','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'mc','auto','「볼」을 바꾸어 만든 낱말 가운데 바꾼 자리가 다른 하나는?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":6,"concept":"K1-2-u5-C3","difficulty":3,"kind":"mc","stem":"「볼」을 바꾸어 만든 낱말 가운데 바꾼 자리가 다른 하나는?","options":[{"t":"복","correct":true},{"t":"돌","mis":"K1-2-u5-X01"},{"t":"솔","mis":"K1-2-u5-X01"}],"explanation":["「돌」과 「솔」은 첫 자음자를 바꿨어요.","「복」은 받침을 바꿨어요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#7','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'match','auto','『국어활동』 58~59쪽 — 「솔」에서 바꾼 자리와 만든 낱말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u5-C3","difficulty":3,"kind":"match","stem":"『국어활동』 58~59쪽 — 「솔」에서 바꾼 자리와 만든 낱말을 이어 보세요.","pairs":[{"l":"첫 자음자를 바꾸면","r":"볼"},{"l":"모음자를 바꾸면","r":"실"},{"l":"받침을 바꾸면","r":"손"}],"mis":"K1-2-u5-X01","explanation":["솔 → 볼 · 실 · 손이에요.","어떻게 바꾸느냐에 따라 다음 낱말이 달라져요.","국어활동 58~59쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#8','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',4,'sa','auto','「감」의 모음자만 「ㅗ」로 바꾸면 어떤 낱말이 되나요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C3","difficulty":4,"kind":"sa","stem":"「감」의 모음자만 「ㅗ」로 바꾸면 어떤 낱말이 되나요?","answer":["곰"],"explanation":["「ㄱ」+「ㅗ」+「ㅁ」은 「곰」이에요.","모음자만 바꿨어요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#9','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',4,'sa','auto','「별」의 받침을 「ㄱ」으로 바꾸면 어떤 낱말이 되나요?','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":4,"kind":"sa","stem":"「별」의 받침을 「ㄱ」으로 바꾸면 어떤 낱말이 되나요?","answer":["벽"],"explanation":["「ㅂ」+「ㅕ」+「ㄱ」은 「벽」이에요.","받침만 바꿨어요.","153쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#10','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',4,'essay','teacher','「공」에서 한 자리만 바꾸어 뜻이 있는 낱말을 두 개 만들고, 어느 자리를 바꾸었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C3","difficulty":4,"kind":"essay","stem":"「공」에서 한 자리만 바꾸어 뜻이 있는 낱말을 두 개 만들고, 어느 자리를 바꾸었는지 쓰세요.","answer_guide":{"answer":"예: 콩 — 첫 자음자 / 강 — 모음자 / 곰 — 받침 — 뜻이 있는 낱말 둘과 바꾼 자리가 맞으면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","한 자리만 바꾸었는가","바꾼 자리 이름을 바르게 썼는가"]},"explanation":["첫 자음자·모음자·받침 가운데 하나만 바꿔요.","뜻이 있는 낱말인지 확인해요.","153쪽 2번의 「공」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#1','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','『국어』 166쪽 — 「그래, 책이야!」에서 몽키가 들고 있는 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":1,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"『국어』 166쪽 — 「그래, 책이야!」에서 몽키가 들고 있는 것은?","options":[{"t":"책","correct":true},{"t":"노트북","mis":"K1-2-u5-X13"},{"t":"휴대 전화","mis":"K1-2-u5-X13"}],"explanation":["몽키는 종이책을 들고 있어요.","노트북을 든 것은 동키예요.","간추림 첫째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#2','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','「그래, 책이야!」에서 동키가 들고 있는 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":2,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"「그래, 책이야!」에서 동키가 들고 있는 것은?","options":[{"t":"노트북","correct":true},{"t":"책","mis":"K1-2-u5-X13"},{"t":"공","mis":"K1-2-u5-X13"}],"explanation":["동키는 노트북을 들고 있어요.","책을 든 것은 몽키예요.","간추림 첫째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#3','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','몽키는 책을 어떻게 읽는 것이라고 알려 주었나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":3,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"몽키는 책을 어떻게 읽는 것이라고 알려 주었나요?","options":[{"t":"한 장씩 넘기며 읽어요","correct":true},{"t":"화면을 눌러 넘겨요","mis":"K1-2-u5-X13"},{"t":"충전해서 읽어요","mis":"K1-2-u5-X13"}],"explanation":["책은 한 장씩 넘기며 읽어요.","화면을 누르거나 충전하는 것은 노트북이에요.","간추림 셋째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#4','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','책을 건네받은 동키는 어떻게 되었나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"책을 건네받은 동키는 어떻게 되었나요?","options":[{"t":"시간 가는 줄 모르고 책에 푹 빠졌어요","correct":true},{"t":"책을 바로 돌려주었어요","mis":"K1-2-u5-X13"},{"t":"노트북만 보았어요","mis":"K1-2-u5-X13"}],"explanation":["동키는 책에 푹 빠졌어요.","몽키가 돌려 달라고 해도 돌려주지 않았어요.","간추림 넷째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#5','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','『국어』 166쪽 — 동키가 책을 돌려주지 않은 까닭은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":5,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"『국어』 166쪽 — 동키가 책을 돌려주지 않은 까닭은?","options":[{"t":"책에 흥미를 느껴 더 읽고 싶었기 때문이에요","correct":true},{"t":"몽키와 싸웠기 때문이에요","mis":"K1-2-u5-X13"},{"t":"책의 배터리가 다 닳았기 때문이에요","mis":"K1-2-u5-X13"}],"explanation":["책이 재미있어서 더 읽고 싶었을 거예요.","싸우거나 배터리가 닳은 일은 없어요.","166쪽 내용 알기예요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#6','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','동키가 다 읽으면 책을 충전해 놓겠다고 한 까닭은?',ARRAY['K1-2-u5-X13','K1-2-u5-X09']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"동키가 다 읽으면 책을 충전해 놓겠다고 한 까닭은?","options":[{"t":"아직 책을 노트북처럼 생각해서","correct":true},{"t":"책에도 충전기가 꼭 필요해서","mis":"K1-2-u5-X13"},{"t":"책이 지루해서","mis":"K1-2-u5-X09"}],"explanation":["동키는 책을 노트북처럼 생각했어요.","책에 빠졌지만 아직 책을 잘 몰랐어요.","간추림 마지막 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#7','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','「재미있는 책」에 들어가지 않는 것은?',ARRAY['K1-2-u5-X09']::text[],false,'{"seq":7,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「재미있는 책」에 들어가지 않는 것은?","options":[{"t":"제목만 보고 읽지 않은 책","correct":true},{"t":"감동적인 이야기가 담긴 책","mis":"K1-2-u5-X09"},{"t":"새롭게 안 정보가 담긴 책","mis":"K1-2-u5-X09"}],"explanation":["감동·놀라움·새로 안 것도 책의 재미예요.","읽지 않은 책은 재미를 알 수 없어요.","166쪽 책에 흥미 가지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#8','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'ox','auto','재미있는 책은 웃긴 이야기가 담긴 책뿐이에요.',ARRAY['K1-2-u5-X09']::text[],false,'{"seq":8,"concept":"K1-2-u5-C4","difficulty":2,"kind":"ox","stem":"재미있는 책은 웃긴 이야기가 담긴 책뿐이에요.","answer":"X","reason_options":[{"t":"감동·놀라움·새로 안 것도 책의 재미니까","correct":true},{"t":"웃기지 않으면 재미가 없으니까","mis":"K1-2-u5-X09"}],"mis":"K1-2-u5-X09","explanation":["재미는 웃음만이 아니에요.","감동적인 이야기, 새로운 정보도 재미있어요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#9','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','『국어』 167쪽 — 동키는 책을 무엇과 비교하고 있나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":9,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"『국어』 167쪽 — 동키는 책을 무엇과 비교하고 있나요?","options":[{"t":"노트북 같은 전자 기기","correct":true},{"t":"사과 같은 과일","mis":"K1-2-u5-X13"},{"t":"자동차","mis":"K1-2-u5-X13"}],"explanation":["동키는 책을 노트북과 비교했어요.","그래서 게임·메일을 물었어요.","167쪽 자신과 관련짓기예요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#10','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',3,'mc','auto','「그래, 책이야!」에서 재미있었던 부분을 알맞게 말한 것은?',ARRAY['K1-2-u5-X10','K1-2-u5-X12']::text[],false,'{"seq":10,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"「그래, 책이야!」에서 재미있었던 부분을 알맞게 말한 것은?","options":[{"t":"책에 푹 빠졌는데 충전하겠다고 하는 장면이 웃겼어","correct":true},{"t":"재미있었어.","mis":"K1-2-u5-X10"},{"t":"노트북은 나쁘고 책만 좋아.","mis":"K1-2-u5-X12"}],"explanation":["어느 장면이 왜 재미있었는지 말했어요.","한마디로 끝내거나 하나를 나쁘다고 하지 않아요.","166쪽 책에 흥미 가지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#1','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',2,'mc','auto','동키가 책으로 할 수 있는지 물어본 것이 아닌 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":1,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"동키가 책으로 할 수 있는지 물어본 것이 아닌 것은?","options":[{"t":"요리하기","correct":true},{"t":"게임","mis":"K1-2-u5-X13"},{"t":"메일 보내기","mis":"K1-2-u5-X13"}],"explanation":["동키는 게임·메일·스크롤·와이파이를 물었어요.","요리하기는 묻지 않았어요.","166쪽 내용 알기예요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#2','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',2,'mc','auto','처음과 비교해 나중에 동키는 어떻게 달라졌나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":2,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"처음과 비교해 나중에 동키는 어떻게 달라졌나요?","options":[{"t":"책을 궁금해하다가 책에 몰입하게 되었어요","correct":true},{"t":"책을 버리고 밖으로 나갔어요","mis":"K1-2-u5-X13"},{"t":"노트북을 더 열심히 보게 되었어요","mis":"K1-2-u5-X13"}],"explanation":["처음엔 책을 노트북처럼 물었어요.","나중엔 시간 가는 줄 모르고 읽었어요.","간추림을 처음과 끝으로 견주어요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#3','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'error','auto','친구가 「이 책을 읽으니 노트북은 나쁘고 책만 좋다는 걸 알았어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X12']::text[],false,'{"seq":3,"concept":"K1-2-u5-C4","difficulty":3,"kind":"error","stem":"친구가 「이 책을 읽으니 노트북은 나쁘고 책만 좋다는 걸 알았어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"하나를 나쁘다고 하지 말고 책이 주는 재미를 말해요","correct":true,"mis_target":"K1-2-u5-X12"},{"t":"맞는 말이에요","mis":"K1-2-u5-X12"},{"t":"노트북이 더 좋다고 해야 해요","mis":"K1-2-u5-X12"}],"explanation":["이 책은 무엇이 나쁘다고 가르치는 책이 아니에요.","동키가 책의 재미에 빠진 이야기예요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#4','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'error','auto','재미있었던 부분을 다르게 고른 친구에게 「네가 틀렸어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X11']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":3,"kind":"error","stem":"재미있었던 부분을 다르게 고른 친구에게 「네가 틀렸어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"재미있게 느낀 부분은 친구마다 다를 수 있어요","correct":true,"mis_target":"K1-2-u5-X11"},{"t":"맞게 말했어요","mis":"K1-2-u5-X11"},{"t":"모두 같은 부분을 골라야 해요","mis":"K1-2-u5-X11"}],"explanation":["사람마다 재미를 느끼는 곳이 달라요.","나누면 책이 더 재미있어져요.","166쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#5','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'error','auto','「그래, 책이야!」를 읽고 「재미있었다.」라고만 말했어요. 무엇이 부족한가요?',ARRAY['K1-2-u5-X10','K1-2-u5-X08']::text[],false,'{"seq":5,"concept":"K1-2-u5-C4","difficulty":3,"kind":"error","stem":"「그래, 책이야!」를 읽고 「재미있었다.」라고만 말했어요. 무엇이 부족한가요?","options":[{"t":"어느 부분이 왜 재미있었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u5-X10"},{"t":"잘 말했어요","mis":"K1-2-u5-X10"},{"t":"책의 쪽수를 말해야 해요","mis":"K1-2-u5-X08"}],"explanation":["어느 장면이 왜 재미있었는지 말해요.","그래야 친구도 함께 느낄 수 있어요.","166쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#6','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'mc','auto','『국어』 167쪽 — 「저는 책을 비행기라고 생각합니다.」 뒤에 이어질 까닭으로 알맞은 것은?',ARRAY['K1-2-u5-X15','K1-2-u5-X08']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"『국어』 167쪽 — 「저는 책을 비행기라고 생각합니다.」 뒤에 이어질 까닭으로 알맞은 것은?","options":[{"t":"나를 어디로든 데려다줄 수 있기 때문입니다","correct":true},{"t":"비행기는 하늘을 날기 때문입니다","mis":"K1-2-u5-X15"},{"t":"책은 무겁기 때문입니다","mis":"K1-2-u5-X08"}],"explanation":["책이 비행기와 닮은 점을 까닭으로 말해요.","비행기 이야기만 하면 책에 대한 생각이 아니에요.","167쪽 (2)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#7','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'mc','auto','『국어』 167쪽 (3) — 동키에게 책을 추천할 때 함께 말하면 좋은 것은?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":7,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"『국어』 167쪽 (3) — 동키에게 책을 추천할 때 함께 말하면 좋은 것은?","options":[{"t":"책 제목과 그 책을 고른 까닭","correct":true},{"t":"책의 값","mis":"K1-2-u5-X08"},{"t":"책의 무게","mis":"K1-2-u5-X08"}],"explanation":["제목과 고른 까닭을 말해요.","값이나 무게로는 책이 재미있는지 몰라요.","167쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#8','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',4,'sa','auto','동키가 들고 있던 전자 기기는 무엇인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C4","difficulty":4,"kind":"sa","stem":"동키가 들고 있던 전자 기기는 무엇인가요?","answer":["노트북"],"explanation":["동키는 노트북을 들고 있었어요.","몽키는 종이책을 들고 있었어요.","간추림 첫째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#9','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',4,'essay','teacher','『국어』 167쪽 — 「저는 책을 ○○(이)라고 생각합니다. 왜냐하면 ~ 때문입니다.」 틀에 맞추어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"『국어』 167쪽 — 「저는 책을 ○○(이)라고 생각합니다. 왜냐하면 ~ 때문입니다.」 틀에 맞추어 쓰세요.","answer_guide":{"answer":"예: 저는 책을 마법이라고 생각합니다. 왜냐하면 책을 읽으면 시간이 무척 빨리 지나가기 때문입니다. — 비유와 까닭이 있으면 맞아요.","scoring_points":["책을 무엇에 빗대었는가","까닭을 썼는가","틀에 맞게 썼는가"]},"explanation":["책과 닮은 것을 떠올려요.","왜 그렇게 생각하는지 까닭을 써요.","167쪽 (2)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#10','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',4,'essay','teacher','동키에게 추천하고 싶은 책의 제목과 그 책을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"동키에게 추천하고 싶은 책의 제목과 그 책을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「바람과 해님」 — 누가 이길지 궁금해서 끝까지 읽게 되는 책이라서 추천해요. — 제목과 까닭이 있으면 맞아요.","scoring_points":["책 제목을 썼는가","고른 까닭을 썼는가","문장이 자연스러운가"]},"explanation":["내가 읽은 책 가운데 인상 깊었던 책을 골라요.","왜 추천하는지 까닭을 써요.","167쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#1','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','『국어』 168쪽 — 선생님의 말씀에 친구들은 뭐라고 했나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":1,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"『국어』 168쪽 — 선생님의 말씀에 친구들은 뭐라고 했나요?","options":[{"t":"「우아!」","correct":true},{"t":"「어휴.」","mis":"K1-2-u5-X13"},{"t":"「싫어요.」","mis":"K1-2-u5-X13"}],"explanation":["친구들은 모두 「우아!」 하고 소리를 질렀어요.","「어휴.」라고 한 것은 「나」예요.","둘째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#2','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','「나」만 「어휴.」라고 한 까닭은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":2,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「나」만 「어휴.」라고 한 까닭은?","options":[{"t":"훌라후프로 운동하는 시간이라서","correct":true},{"t":"운동장에 비가 와서","mis":"K1-2-u5-X13"},{"t":"친구와 다투어서","mis":"K1-2-u5-X13"}],"explanation":["「왜냐하면」 뒤에 까닭이 있어요.","훌라후프로 운동하는 시간이었어요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#3','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','「나」가 훌라후프를 돌리면 어떻게 되나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":3,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「나」가 훌라후프를 돌리면 어떻게 되나요?","options":[{"t":"금방 뚝 떨어져요","correct":true},{"t":"오래오래 잘 돌아가요","mis":"K1-2-u5-X13"},{"t":"하늘로 날아가요","mis":"K1-2-u5-X13"}],"explanation":["「나」가 하면 금방 뚝 떨어져요.","친구들은 떨어지지 않게 잘 돌려요.","다섯째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#4','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','선생님은 「나」의 어떤 모습을 칭찬하셨나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":4,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"선생님은 「나」의 어떤 모습을 칭찬하셨나요?","options":[{"t":"포기하지 않고 노력하는 모습","correct":true},{"t":"훌라후프를 가장 잘 돌리는 모습","mis":"K1-2-u5-X13"},{"t":"조용히 앉아 있는 모습","mis":"K1-2-u5-X13"}],"explanation":["포기하지 않고 노력하는 모습이 기특하다고 하셨어요.","가장 잘 돌린 것은 아니에요.","일곱째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#5','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',2,'mc','auto','『국어』 170쪽 2번 — 글쓴이에게 있었던 일의 차례로 알맞은 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":5,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"『국어』 170쪽 2번 — 글쓴이에게 있었던 일의 차례로 알맞은 것은?","options":[{"t":"운동장에 나감 → 잘 돌리지 못함 → 노력함 → 칭찬을 받음","correct":true},{"t":"칭찬을 받음 → 운동장에 나감 → 노력함 → 잘 돌리지 못함","mis":"K1-2-u5-X13"},{"t":"노력함 → 칭찬을 받음 → 잘 돌리지 못함 → 운동장에 나감","mis":"K1-2-u5-X13"}],"explanation":["있었던 일을 차례대로 정리해요.","그러면 내용이 한눈에 보여요.","170쪽 2번이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#6','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',2,'match','auto','『국어』 170쪽 2번 — 있었던 일과 글쓴이의 마음을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"『국어』 170쪽 2번 — 있었던 일과 글쓴이의 마음을 이어 보세요.","pairs":[{"l":"운동장에 나가자는 말을 들었을 때","r":"하기 싫은 마음"},{"l":"친구들이 잘 돌리는 것을 볼 때","r":"부러운 마음"},{"l":"선생님께 칭찬을 받았을 때","r":"뿌듯한 마음"}],"mis":"K1-2-u5-X14","explanation":["일이 달라지면 마음도 달라져요.","나라면 어땠을지 떠올려요.","170쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#7','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',2,'mc','auto','「나」가 훌라후프를 잘 돌리고 싶어서 한 일은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":7,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「나」가 훌라후프를 잘 돌리고 싶어서 한 일은?","options":[{"t":"훌라후프가 있다고 생각하며 허리를 이리저리 움직였어요","correct":true},{"t":"훌라후프를 몰래 숨겼어요","mis":"K1-2-u5-X13"},{"t":"교실로 들어가 버렸어요","mis":"K1-2-u5-X13"}],"explanation":["훌라후프 없이도 허리를 움직이며 연습했어요.","숨기거나 들어간 일은 없어요.","여섯째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#8','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',2,'mc','auto','『국어』 171쪽 3번 — 글쓴이가 한 일에 대한 생각이나 느낌으로 알맞은 것은?',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":8,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"『국어』 171쪽 3번 — 글쓴이가 한 일에 대한 생각이나 느낌으로 알맞은 것은?","options":[{"t":"노력하는 모습이 대단하다고 생각해","correct":true},{"t":"훌라후프는 동그랗게 생겼어","mis":"K1-2-u5-X15"},{"t":"나는 어제 떡볶이를 먹었어","mis":"K1-2-u5-X15"}],"explanation":["글쓴이가 한 일(노력)에 대한 생각이에요.","글쓴이가 한 일과 상관없는 말은 알맞지 않아요.","171쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#9','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',2,'ox','auto','「좋았다.」라고만 말해도 생각이나 느낌을 구체적으로 말한 것이에요.',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":9,"concept":"K1-2-u5-C6","difficulty":2,"kind":"ox","stem":"「좋았다.」라고만 말해도 생각이나 느낌을 구체적으로 말한 것이에요.","answer":"X","reason_options":[{"t":"글의 어느 부분 때문에 그렇게 느꼈는지 함께 말해야 구체적이니까","correct":true},{"t":"짧게 말할수록 구체적이니까","mis":"K1-2-u5-X10"}],"mis":"K1-2-u5-X10","explanation":["「좋았다.」만으로는 무엇이 좋았는지 몰라요.","어느 부분 때문인지 넣어 말해요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#10','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',3,'mc','auto','글쓴이와 비슷한 경험으로 알맞은 것은?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":10,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"글쓴이와 비슷한 경험으로 알맞은 것은?","options":[{"t":"다른 친구들은 잘하는데 나만 줄넘기를 못해서 속상했던 일","correct":true},{"t":"친구와 맛있는 과자를 나누어 먹은 일","mis":"K1-2-u5-X16"},{"t":"가게에서 훌라후프를 산 일","mis":"K1-2-u5-X16"}],"explanation":["하는 일이 달라도 마음이 비슷하면 비슷한 경험이에요.","훌라후프가 나와도 마음이 다르면 비슷하지 않아요.","지도서 228쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#1','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',2,'mc','auto','칭찬을 받은 뒤 「나」의 마음은?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":1,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"칭찬을 받은 뒤 「나」의 마음은?","options":[{"t":"기분이 좋았지만 다음에는 더 잘 돌리고 싶어요","correct":true},{"t":"기분이 나빠서 그만두고 싶어요","mis":"K1-2-u5-X14"},{"t":"아무 마음도 들지 않아요","mis":"K1-2-u5-X14"}],"explanation":["칭찬을 받아 기분이 좋았어요.","그래도 친구들처럼 잘 돌리고 싶어요.","마지막 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#2','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',2,'mc','auto','「칭찬을 받아서 기분이 좋았지만 잘 돌리고 싶은 마음이 느껴져서 ___」에 알맞은 말은?',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":2,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"「칭찬을 받아서 기분이 좋았지만 잘 돌리고 싶은 마음이 느껴져서 ___」에 알맞은 말은?","options":[{"t":"응원해 주고 싶어","correct":true},{"t":"훌라후프는 재미없어","mis":"K1-2-u5-X15"},{"t":"나랑은 상관없어","mis":"K1-2-u5-X15"}],"explanation":["글쓴이의 마음에 대한 내 느낌이에요.","글쓴이와 상관없는 말은 알맞지 않아요.","171쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#3','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',3,'error','auto','친구가 「나는 훌라후프를 제일 잘 돌려서 칭찬을 받았다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":3,"concept":"K1-2-u5-C5","difficulty":3,"kind":"error","stem":"친구가 「나는 훌라후프를 제일 잘 돌려서 칭찬을 받았다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"글에 없는 일이에요 — 포기하지 않고 노력해서 칭찬을 받았어요","correct":true,"mis_target":"K1-2-u5-X13"},{"t":"잘 정리했어요","mis":"K1-2-u5-X13"},{"t":"칭찬은 받지 않았어요","mis":"K1-2-u5-X13"}],"explanation":["「나」는 아직 잘 돌리지 못해요.","노력하는 모습을 칭찬받았어요.","일곱째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#4','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',3,'error','auto','「어휴.」라고 했을 때 글쓴이가 신났을 거라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":4,"concept":"K1-2-u5-C5","difficulty":3,"kind":"error","stem":"「어휴.」라고 했을 때 글쓴이가 신났을 거라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"훌라후프를 잘 못 돌려서 하기 싫은 마음이었어요","correct":true,"mis_target":"K1-2-u5-X14"},{"t":"맞게 짐작했어요","mis":"K1-2-u5-X14"},{"t":"글쓴이는 아무 마음도 없었어요","mis":"K1-2-u5-X14"}],"explanation":["신난 것은 「우아!」 한 친구들이에요.","「어휴.」에는 하기 싫은 마음이 담겨 있어요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#5','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',3,'error','auto','생각을 말해 보라고 했더니 「칭찬을 받아서 기분이 좋았지만 다음에는 잘 돌리면 좋겠다.」라고 그대로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":5,"concept":"K1-2-u5-C6","difficulty":3,"kind":"error","stem":"생각을 말해 보라고 했더니 「칭찬을 받아서 기분이 좋았지만 다음에는 잘 돌리면 좋겠다.」라고 그대로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"글쓴이의 말을 그대로 옮겼어요 — 그 부분을 읽고 내 마음이 어땠는지 말해요","correct":true,"mis_target":"K1-2-u5-X15"},{"t":"잘 말했어요","mis":"K1-2-u5-X15"},{"t":"더 크게 읽어야 해요","mis":"K1-2-u5-X15"}],"explanation":["글에 있는 문장은 글쓴이의 생각이에요.","그것을 읽고 든 내 생각을 말해요.","지도서 238쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#6','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',3,'error','auto','친구가 「나는 훌라후프를 돌린 적이 없으니 비슷한 경험이 없어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":6,"concept":"K1-2-u5-C6","difficulty":3,"kind":"error","stem":"친구가 「나는 훌라후프를 돌린 적이 없으니 비슷한 경험이 없어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"하는 일이 같지 않아도 마음이 비슷하면 비슷한 경험이에요","correct":true,"mis_target":"K1-2-u5-X16"},{"t":"맞는 말이에요","mis":"K1-2-u5-X16"},{"t":"훌라후프를 사서 해 봐야 해요","mis":"K1-2-u5-X16"}],"explanation":["줄넘기·받아쓰기·젓가락질도 비슷한 경험이에요.","나만 못해서 속상했던 마음이 닮았어요.","지도서 228쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#7','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',3,'mc','auto','생각이나 느낌을 구체적으로 나타낸 말은?',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":7,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"생각이나 느낌을 구체적으로 나타낸 말은?","options":[{"t":"훌라후프가 있다고 생각하며 허리를 돌린 것이 재치 있어","correct":true},{"t":"재미있었다.","mis":"K1-2-u5-X10"},{"t":"좋았다.","mis":"K1-2-u5-X10"}],"explanation":["글의 어느 부분 때문인지 드러나요.","한마디로 끝난 말은 구체적이지 않아요.","171쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#8','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',4,'sa','auto','「나」가 「어휴.」라고 한 까닭이 된 운동 기구는 무엇인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C5","difficulty":4,"kind":"sa","stem":"「나」가 「어휴.」라고 한 까닭이 된 운동 기구는 무엇인가요?","answer":["훌라후프"],"explanation":["훌라후프로 운동하는 시간이었어요.","「나」는 훌라후프를 잘 돌리지 못했어요.","셋째 줄이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#9','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',4,'essay','teacher','『국어』 171쪽 — 글쓴이가 한 일에 대한 내 생각이나 느낌을 글의 어느 부분 때문인지 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"『국어』 171쪽 — 글쓴이가 한 일에 대한 내 생각이나 느낌을 글의 어느 부분 때문인지 넣어 쓰세요.","answer_guide":{"answer":"예: 훌라후프가 없어도 허리를 이리저리 움직이며 연습한 부분을 읽고, 포기하지 않는 모습이 대단하다고 생각했어. — 글의 부분과 내 생각이 함께 있으면 맞아요.","scoring_points":["글의 어느 부분인지 썼는가","내 생각이나 느낌을 썼는가","글쓴이의 말을 그대로 옮기지 않았는가"]},"explanation":["글쓴이가 한 일을 먼저 짚어요.","그 부분을 읽고 든 내 마음을 써요.","171쪽 3번이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#10','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',4,'essay','teacher','다른 친구들은 잘하는데 나만 잘하지 못해서 속상했던 일을 쓰고, 그때 내 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"다른 친구들은 잘하는데 나만 잘하지 못해서 속상했던 일을 쓰고, 그때 내 마음을 쓰세요.","answer_guide":{"answer":"예: 친구들은 줄넘기를 열 번 넘게 하는데 나는 두 번 만에 걸려서 속상했어요. — 있었던 일과 마음이 있으면 맞아요.","scoring_points":["있었던 일을 썼는가","그때 마음을 썼는가","글쓴이와 마음이 닮은 경험인가"]},"explanation":["꼭 훌라후프가 아니어도 돼요.","그때 어떤 마음이었는지 써요.","지도서 228쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#1','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','『국어』 172쪽 — 독서 계단에 가장 먼저 읽고 싶은 책은 어디에 쓰나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":1,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"『국어』 172쪽 — 독서 계단에 가장 먼저 읽고 싶은 책은 어디에 쓰나요?","options":[{"t":"맨 아래 첫 번째 계단","correct":true},{"t":"가장 높은 계단","mis":"K1-2-u5-X17"},{"t":"아무 칸에나","mis":"K1-2-u5-X17"}],"explanation":["맨 아래쪽 빈칸부터 책 제목을 써요.","가장 나중에 읽을 책이 가장 높은 계단이에요.","172쪽이에요."],"asset":{"type":"scene","icon":"🪜📚","text":"독서 계단 — 맨 아래 칸부터 차례대로 읽고 다 읽으면 색칠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#2','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','독서 계단은 언제 색칠하나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":2,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계단은 언제 색칠하나요?","options":[{"t":"그 책을 다 읽었을 때","correct":true},{"t":"책 제목을 썼을 때","mis":"K1-2-u5-X17"},{"t":"책을 빌려 왔을 때","mis":"K1-2-u5-X17"}],"explanation":["다 읽은 책의 계단을 색칠해요.","한 칸씩 오르는 기쁨을 느껴요.","172쪽이에요."],"asset":{"type":"scene","icon":"🪜📚","text":"독서 계단 — 맨 아래 칸부터 차례대로 읽고 다 읽으면 색칠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#3','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','독서 계단의 책은 어떻게 읽나요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":3,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계단의 책은 어떻게 읽나요?","options":[{"t":"한 권을 처음부터 끝까지 온전히 읽어요","correct":true},{"t":"앞부분만 훑어 읽어요","mis":"K1-2-u5-X19"},{"t":"재미있는 쪽만 뛰어 읽어요","mis":"K1-2-u5-X19"}],"explanation":["한 권을 끝까지 읽고 다음 계단으로 가요.","훑어 읽거나 뛰어 읽지 않아요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#4','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','『국어』 173쪽 — 책 보물 찾기에서 보물 쪽지의 질문에 답하려면 어떻게 해야 하나요?',ARRAY['K1-2-u5-X18']::text[],false,'{"seq":4,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"『국어』 173쪽 — 책 보물 찾기에서 보물 쪽지의 질문에 답하려면 어떻게 해야 하나요?","options":[{"t":"그 책을 읽어야 해요","correct":true},{"t":"쪽지를 많이 모아야 해요","mis":"K1-2-u5-X18"},{"t":"제일 빨리 달려야 해요","mis":"K1-2-u5-X18"}],"explanation":["쪽지의 답은 책 속에 있어요.","진짜 보물은 책을 읽는 거예요.","173쪽 예시 1이에요."],"asset":{"type":"passage","lines":["선생님이 학급 문고의 책 사이에 보물 쪽지를 숨겨 둬요.","「책 보물 찾기 시작!」 하면 쪽지를 찾아요. 한 사람이 두 개까지만 찾아요.","쪽지에 쓰인 질문의 답을 책을 읽고 써서 선생님께 내요.","선생님이 답을 확인하면 쪽지를 작은 선물로 바꿔 줘요."],"title":"『국어』 173쪽 — 책 보물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#5','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'mc','auto','읽고 싶은 책을 고를 때 생각할 것은?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":5,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"읽고 싶은 책을 고를 때 생각할 것은?","options":[{"t":"나의 흥미와 읽기 수준","correct":true},{"t":"가장 두꺼운 책인지","mis":"K1-2-u5-X08"},{"t":"표지 색깔이 무엇인지","mis":"K1-2-u5-X08"}],"explanation":["재미있게 읽은 책, 알고 싶은 내용을 떠올려요.","나에게 맞는 책을 골라요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#6','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'mc','auto','책 읽기가 아직 어렵다면 첫 번째 계단에는 어떤 책을 쓰면 좋을까요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":6,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"책 읽기가 아직 어렵다면 첫 번째 계단에는 어떤 책을 쓰면 좋을까요?","options":[{"t":"읽기 쉽고 가장 흥미 있는 책","correct":true},{"t":"글자가 가장 많은 책","mis":"K1-2-u5-X19"},{"t":"친구가 어렵다고 한 책","mis":"K1-2-u5-X19"}],"explanation":["처음에 끝까지 읽어 낸 경험이 있어야 해요.","그래야 계속 읽고 싶어져요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#7','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'match','auto','『국어』 173쪽 — 책 카페 놀이에서 역할과 하는 일을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":2,"kind":"match","stem":"『국어』 173쪽 — 책 카페 놀이에서 역할과 하는 일을 이어 보세요.","pairs":[{"l":"카페 주인","r":"내 책을 소개하고 읽어 줘요"},{"l":"손님","r":"관심 가는 책 카페에 앉아 듣고 소감을 말해요"},{"l":"소감을 들은 주인","r":"간식을 주거나 도장을 찍어 줘요"}],"mis":"K1-2-u5-X18","explanation":["주인은 책을 소개하고, 손님은 듣고 소감을 말해요.","책으로 친구와 이야기를 나눠요.","173쪽 예시 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#8','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'mc','auto','독서 계획을 세우면 좋은 점은?',ARRAY['K1-2-u5-X19','K1-2-u5-X18']::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"독서 계획을 세우면 좋은 점은?","options":[{"t":"책을 얼마나 읽었는지 점검할 수 있어요","correct":true},{"t":"책을 대충 훑어보게 돼요","mis":"K1-2-u5-X19"},{"t":"도서관에 갈 필요가 없어져요","mis":"K1-2-u5-X18"}],"explanation":["계획을 세우면 읽으려는 마음이 커져요.","얼마나 읽었는지도 알 수 있어요.","172쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#9','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'ox','auto','책 보물 찾기에서는 보물 쪽지를 많이 찾을수록 좋아요.',ARRAY['K1-2-u5-X18']::text[],false,'{"seq":9,"concept":"K1-2-u5-C7","difficulty":2,"kind":"ox","stem":"책 보물 찾기에서는 보물 쪽지를 많이 찾을수록 좋아요.","answer":"X","reason_options":[{"t":"한 사람이 두 개까지만 찾고 쪽지의 질문에 답하려고 책을 읽는 활동이니까","correct":true},{"t":"쪽지를 많이 모은 사람이 이기는 놀이니까","mis":"K1-2-u5-X18"}],"mis":"K1-2-u5-X18","explanation":["한 사람이 두 개까지만 찾아요.","쪽지의 답을 쓰려면 책을 읽어야 해요.","173쪽 예시 1이에요."],"asset":{"type":"passage","lines":["선생님이 학급 문고의 책 사이에 보물 쪽지를 숨겨 둬요.","「책 보물 찾기 시작!」 하면 쪽지를 찾아요. 한 사람이 두 개까지만 찾아요.","쪽지에 쓰인 질문의 답을 책을 읽고 써서 선생님께 내요.","선생님이 답을 확인하면 쪽지를 작은 선물로 바꿔 줘요."],"title":"『국어』 173쪽 — 책 보물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#10','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',3,'mc','auto','독서 계단을 다 오른 뒤에 이어 가면 좋은 것은?',ARRAY['K1-2-u5-X19','K1-2-u5-X18']::text[],false,'{"seq":10,"concept":"K1-2-u5-C7","difficulty":3,"kind":"mc","stem":"독서 계단을 다 오른 뒤에 이어 가면 좋은 것은?","options":[{"t":"독서 마라톤이나 독서 통장처럼 계속 읽기","correct":true},{"t":"책 읽기를 그만두기","mis":"K1-2-u5-X19"},{"t":"친구와 읽은 권수 겨루기","mis":"K1-2-u5-X18"}],"explanation":["계획을 계속 이어 가면 읽는 습관이 생겨요.","겨루기가 아니라 꾸준히 읽기예요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#1','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',2,'mc','auto','가장 나중에 읽을 책은 독서 계단 어디에 쓰나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":1,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"가장 나중에 읽을 책은 독서 계단 어디에 쓰나요?","options":[{"t":"가장 높은 계단","correct":true},{"t":"맨 아래 계단","mis":"K1-2-u5-X17"},{"t":"계단 밖","mis":"K1-2-u5-X17"}],"explanation":["읽고 싶은 차례대로 아래부터 써요.","가장 나중에 읽을 책은 가장 높은 계단이에요.","172쪽이에요."],"asset":{"type":"scene","icon":"🪜📚","text":"독서 계단 — 맨 아래 칸부터 차례대로 읽고 다 읽으면 색칠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
