INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#3','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'error','auto','친구가 독서 계단에 제목을 쓰자마자 모든 칸을 색칠했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":3,"concept":"K1-2-u5-C7","difficulty":3,"kind":"error","stem":"친구가 독서 계단에 제목을 쓰자마자 모든 칸을 색칠했어요. 무엇이 잘못되었나요?","options":[{"t":"다 읽은 책만 한 칸씩 색칠해요","correct":true,"mis_target":"K1-2-u5-X17"},{"t":"잘했어요","mis":"K1-2-u5-X17"},{"t":"색칠은 하지 않아요","mis":"K1-2-u5-X17"}],"explanation":["색칠은 다 읽었다는 표시예요.","한 권씩 읽고 한 칸씩 색칠해요.","172쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#4','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'error','auto','친구가 「제일 두꺼운 책을 첫 번째 계단에 쓸래.」라고 했어요. 무엇을 고치면 좋을까요?',ARRAY['K1-2-u5-X19','K1-2-u5-X17']::text[],false,'{"seq":4,"concept":"K1-2-u5-C7","difficulty":3,"kind":"error","stem":"친구가 「제일 두꺼운 책을 첫 번째 계단에 쓸래.」라고 했어요. 무엇을 고치면 좋을까요?","options":[{"t":"읽기 쉽고 흥미 있는 책을 첫 계단에 써요","correct":true,"mis_target":"K1-2-u5-X19"},{"t":"잘 정했어요","mis":"K1-2-u5-X19"},{"t":"가장 높은 계단에 써야 해요","mis":"K1-2-u5-X17"}],"explanation":["첫 계단에서 끝까지 읽는 경험이 중요해요.","두께가 아니라 흥미와 수준으로 골라요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#5','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'error','auto','친구가 책 여러 권의 앞부분만 넘겨 보고 계단을 모두 색칠했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X19','K1-2-u5-X17']::text[],false,'{"seq":5,"concept":"K1-2-u5-C7","difficulty":3,"kind":"error","stem":"친구가 책 여러 권의 앞부분만 넘겨 보고 계단을 모두 색칠했어요. 무엇이 잘못되었나요?","options":[{"t":"한 권을 끝까지 읽고 나서 색칠해요","correct":true,"mis_target":"K1-2-u5-X19"},{"t":"잘했어요","mis":"K1-2-u5-X19"},{"t":"색칠을 더 진하게 해야 해요","mis":"K1-2-u5-X17"}],"explanation":["훑어보기만 하면 다 읽은 것이 아니에요.","한 권을 온전히 읽어요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
