INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#7','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'match','auto','『국어』 173쪽 — 책 보물 찾기 차례를 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":3,"kind":"match","stem":"『국어』 173쪽 — 책 보물 찾기 차례를 이어 보세요.","pairs":[{"l":"①","r":"책 사이에 숨겨 둔 보물 쪽지를 찾아요"},{"l":"②","r":"쪽지의 질문에 대한 답을 책을 읽고 써요"},{"l":"③","r":"답을 확인받고 작은 선물로 바꿔요"}],"mis":"K1-2-u5-X18","explanation":["찾기 → 읽고 답 쓰기 → 확인받기예요.","답을 쓰려면 책을 읽어야 해요.","173쪽 예시 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#8','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',4,'sa','auto','독서 계단에서 다 읽은 책의 칸에는 무엇을 하나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":4,"kind":"sa","stem":"독서 계단에서 다 읽은 책의 칸에는 무엇을 하나요? 한 낱말로 쓰세요.","answer":["색칠","색칠해요","색칠하기","색칠한다"],"explanation":["다 읽으면 그 계단을 색칠해요.","한 칸씩 오르는 기쁨을 느껴요.","172쪽이에요."],"asset":{"type":"scene","icon":"🪜📚","text":"독서 계단 — 맨 아래 칸부터 차례대로 읽고 다 읽으면 색칠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#9','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',4,'essay','teacher','독서 계단의 첫 번째 계단에 쓸 책을 정하고, 그 책을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C7","difficulty":4,"kind":"essay","stem":"독서 계단의 첫 번째 계단에 쓸 책을 정하고, 그 책을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「젊어지는 샘물」 — 그림이 많아서 쉽게 읽을 수 있고, 샘물을 마시면 어떻게 될지 궁금해서요. — 책 제목과 까닭이 있으면 맞아요.","scoring_points":["책 제목을 썼는가","흥미나 읽기 수준과 관련된 까닭인가","문장이 자연스러운가"]},"explanation":["읽기 쉽고 흥미 있는 책을 골라요.","왜 고르는지 까닭을 써요.","172쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#10','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',4,'essay','teacher','우리 반에서 하고 싶은 책 활동을 하나 정하고, 하고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C7","difficulty":4,"kind":"essay","stem":"우리 반에서 하고 싶은 책 활동을 하나 정하고, 하고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 책 카페 놀이 — 내가 좋아하는 책을 친구들에게 소개하고 싶어서요. — 활동과 까닭이 있으면 맞아요.","scoring_points":["책 활동을 하나 정했는가","하고 싶은 까닭을 썼는가","책을 읽는 일과 이어지는가"]},"explanation":["책 보물 찾기, 책 카페 놀이 가운데 골라도 돼요.","하고 싶은 까닭을 써요.","173쪽 우리가 활동을 정해요예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#1','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C1',1,'mc','auto','『국어』 174쪽 — 안내판의 「밤」과 「람」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 174쪽 — 안내판의 「밤」과 「람」은 어느 자리가 다른가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["「ㅂ」과 「ㄹ」, 첫 자음자만 달라요.","모음자 「ㅏ」와 받침 「ㅁ」은 같아요.","174쪽 1번이에요."],"asset":{"type":"passage","lines":["도토리와 밤은 겨울철 야생 동물의 먹이입니다.","다람쥐에게 도토리를 돌려주세요!"],"title":"『국어』 174쪽 — 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#2','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',1,'mc','auto','「ㄱ」에 한 획을 더하면 어떤 자음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"「ㄱ」에 한 획을 더하면 어떤 자음자가 되나요?","options":[{"t":"ㅋ","correct":true},{"t":"ㄴ","mis":"K1-2-u5-X06"},{"t":"ㄷ","mis":"K1-2-u5-X06"}],"explanation":["「ㄱ」에 획을 더하면 「ㅋ」이에요.","소리가 더 세져요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#3','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',1,'mc','auto','『국어』 175쪽 2번 — 친구들이 설명하는 글자는?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 175쪽 2번 — 친구들이 설명하는 글자는?","options":[{"t":"한글","correct":true},{"t":"한자","mis":"K1-2-u5-X04"},{"t":"영어 알파벳","mis":"K1-2-u5-X04"}],"explanation":["누가, 왜, 언제 만들었는지 알려진 글자는 한글이에요.","한자는 한글 전에 빌려 쓰던 글자예요.","175쪽 2번이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"글자를 만든 사람이 누구인지 알아."},{"who":"친구 2","text":"그리고 글자를 왜 만들었는지도 알아."},{"who":"친구 3","text":"만든 글자를 언제 발표했는지 알아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#4','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',1,'mc','auto','『국어』 175쪽 3번 — 「손」의 첫 자음자만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 175쪽 3번 — 「손」의 첫 자음자만 바꾼 낱말은?","options":[{"t":"돈","correct":true},{"t":"산","mis":"K1-2-u5-X01"},{"t":"솜","mis":"K1-2-u5-X01"}],"explanation":["「ㅅ」을 「ㄷ」으로 바꾸면 「돈」이에요.","「산」은 모음자, 「솜」은 받침을 바꿨어요.","175쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#5','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C8',1,'mc','auto','『국어』 176쪽 — 「종이 한 ( )」에 알맞은 말은?',ARRAY['K1-2-u5-X20']::text[],false,'{"seq":5,"concept":"K1-2-u5-C8","difficulty":1,"kind":"mc","stem":"『국어』 176쪽 — 「종이 한 ( )」에 알맞은 말은?","options":[{"t":"장","correct":true},{"t":"자루","mis":"K1-2-u5-X20"},{"t":"대","mis":"K1-2-u5-X20"}],"explanation":["종이는 「장」으로 세요.","종이 한 장이에요.","176쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#6','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C4',1,'mc','auto','「그래, 책이야!」에서 몽키가 들고 있는 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"「그래, 책이야!」에서 몽키가 들고 있는 것은?","options":[{"t":"책","correct":true},{"t":"노트북","mis":"K1-2-u5-X13"},{"t":"휴대 전화","mis":"K1-2-u5-X13"}],"explanation":["몽키는 종이책을 들고 있어요.","노트북은 동키가 들고 있어요.","간추림 첫째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#7','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C5',1,'mc','auto','「나」만 「어휴.」라고 한 까닭은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":7,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「나」만 「어휴.」라고 한 까닭은?","options":[{"t":"훌라후프로 운동하는 시간이라서","correct":true},{"t":"운동장에 비가 와서","mis":"K1-2-u5-X13"},{"t":"친구와 다투어서","mis":"K1-2-u5-X13"}],"explanation":["「왜냐하면」 뒤에 까닭이 있어요.","훌라후프로 운동하는 시간이었어요.","168쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#8','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C7',1,'mc','auto','독서 계단에 가장 먼저 읽고 싶은 책은 어디에 쓰나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계단에 가장 먼저 읽고 싶은 책은 어디에 쓰나요?","options":[{"t":"맨 아래 첫 번째 계단","correct":true},{"t":"가장 높은 계단","mis":"K1-2-u5-X17"},{"t":"아무 칸에나","mis":"K1-2-u5-X17"}],"explanation":["맨 아래쪽 빈칸부터 써요.","읽고 싶은 차례대로 올라가요.","172쪽이에요."],"asset":{"type":"scene","icon":"🪜📚","text":"독서 계단 — 맨 아래 칸부터 차례대로 읽고 다 읽으면 색칠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
