INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#10','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',2,'match','auto','한 획을 더해 만든 자음자를 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":2,"kind":"match","stem":"한 획을 더해 만든 자음자를 이어 보세요.","pairs":[{"l":"ㄱ","r":"ㅋ"},{"l":"ㄷ","r":"ㅌ"},{"l":"ㅈ","r":"ㅊ"}],"mis":"K1-2-u5-X06","explanation":["ㄱ→ㅋ, ㄷ→ㅌ, ㅈ→ㅊ이에요.","소리가 더 세져요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#11','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',2,'mc','auto','「볼」의 모음자만 바꾼 낱말이 아닌 것은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":11,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「볼」의 모음자만 바꾼 낱말이 아닌 것은?","options":[{"t":"봉","correct":true},{"t":"발","mis":"K1-2-u5-X01"},{"t":"별","mis":"K1-2-u5-X01"}],"explanation":["「발」과 「별」은 모음자를 바꿨어요.","「봉」은 받침을 바꿨어요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#12','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C4',2,'ox','auto','재미있는 책은 웃긴 이야기가 담긴 책뿐이에요.',ARRAY['K1-2-u5-X09']::text[],false,'{"seq":12,"concept":"K1-2-u5-C4","difficulty":2,"kind":"ox","stem":"재미있는 책은 웃긴 이야기가 담긴 책뿐이에요.","answer":"X","reason_options":[{"t":"감동·놀라움·새로 안 것도 책의 재미니까","correct":true},{"t":"웃기지 않으면 재미가 없으니까","mis":"K1-2-u5-X09"}],"mis":"K1-2-u5-X09","explanation":["재미는 웃음만이 아니에요.","감동과 새로 안 것도 재미예요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#13','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C5',2,'mc','auto','글쓴이에게 있었던 일의 차례로 알맞은 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":13,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"글쓴이에게 있었던 일의 차례로 알맞은 것은?","options":[{"t":"운동장에 나감 → 잘 돌리지 못함 → 노력함 → 칭찬을 받음","correct":true},{"t":"칭찬을 받음 → 운동장에 나감 → 노력함 → 잘 돌리지 못함","mis":"K1-2-u5-X13"},{"t":"노력함 → 칭찬을 받음 → 잘 돌리지 못함 → 운동장에 나감","mis":"K1-2-u5-X13"}],"explanation":["있었던 일을 차례대로 정리해요.","내용이 한눈에 보여요.","170쪽 2번이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#14','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',2,'mc','auto','글쓴이가 한 일에 대한 생각이나 느낌으로 알맞은 것은?',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":14,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"글쓴이가 한 일에 대한 생각이나 느낌으로 알맞은 것은?","options":[{"t":"노력하는 모습이 대단하다고 생각해","correct":true},{"t":"훌라후프는 동그랗게 생겼어","mis":"K1-2-u5-X15"},{"t":"나는 어제 떡볶이를 먹었어","mis":"K1-2-u5-X15"}],"explanation":["글쓴이가 한 일에 대한 생각이에요.","상관없는 말은 알맞지 않아요.","171쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#15','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C8',2,'match','auto','『국어』 176쪽 — 물건과 세는 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"K1-2-u5-C8","difficulty":2,"kind":"match","stem":"『국어』 176쪽 — 물건과 세는 말을 이어 보세요.","pairs":[{"l":"종이 한","r":"장"},{"l":"연필 한","r":"자루"},{"l":"차 한","r":"대"}],"mis":"K1-2-u5-X20","explanation":["종이 한 장, 연필 한 자루예요.","차 한 대예요.","176쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#16','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C1',2,'ox','auto','글자가 하나만 달라져도 소리와 뜻이 달라져요.',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":16,"concept":"K1-2-u5-C1","difficulty":2,"kind":"ox","stem":"글자가 하나만 달라져도 소리와 뜻이 달라져요.","answer":"O","reason_options":[{"t":"「금」과 「음」처럼 한 자리만 달라도 다른 글자가 되니까","correct":true},{"t":"모양이 비슷하면 소리와 뜻도 같으니까","mis":"K1-2-u5-X03"}],"mis":"K1-2-u5-X03","explanation":["하나만 달라도 다른 글자예요.","소리와 뜻이 달라져요.","149쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#17','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C1',3,'error','auto','친구가 「금」과 모양이 비슷한 글자로 「금도끼」의 「금」을 골랐어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X02']::text[],false,'{"seq":17,"concept":"K1-2-u5-C1","difficulty":3,"kind":"error","stem":"친구가 「금」과 모양이 비슷한 글자로 「금도끼」의 「금」을 골랐어요. 무엇이 잘못되었나요?","options":[{"t":"똑같은 글자예요 — 하나만 다른 비슷한 글자를 찾아요","correct":true,"mis_target":"K1-2-u5-X02"},{"t":"잘 골랐어요","mis":"K1-2-u5-X02"},{"t":"「도」를 골라야 해요","mis":"K1-2-u5-X02"}],"explanation":["똑같은 글자는 비슷한 글자가 아니에요.","「음」처럼 하나만 다른 글자를 찾아요.","148쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#18','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',3,'error','auto','친구가 「ㄱ보다 ㅋ의 소리가 더 약해요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":18,"concept":"K1-2-u5-C2","difficulty":3,"kind":"error","stem":"친구가 「ㄱ보다 ㅋ의 소리가 더 약해요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"획을 더한 「ㅋ」의 소리가 더 세요","correct":true,"mis_target":"K1-2-u5-X06"},{"t":"맞는 말이에요","mis":"K1-2-u5-X06"},{"t":"두 소리는 똑같아요","mis":"K1-2-u5-X06"}],"explanation":["획을 더하면 소리가 세져요.","「ㅋ」이 더 세요.","150쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#19','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C4',3,'error','auto','친구가 「이 책을 읽으니 노트북은 나쁘고 책만 좋다는 걸 알았어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X12']::text[],false,'{"seq":19,"concept":"K1-2-u5-C4","difficulty":3,"kind":"error","stem":"친구가 「이 책을 읽으니 노트북은 나쁘고 책만 좋다는 걸 알았어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"하나를 나쁘다고 하지 말고 책이 주는 재미를 말해요","correct":true,"mis_target":"K1-2-u5-X12"},{"t":"맞는 말이에요","mis":"K1-2-u5-X12"},{"t":"노트북이 더 좋다고 해야 해요","mis":"K1-2-u5-X12"}],"explanation":["하나를 나쁘다고 정하지 않아요.","책이 주는 재미를 말해요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#20','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C5',3,'error','auto','친구가 「나는 훌라후프를 제일 잘 돌려서 칭찬을 받았다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":20,"concept":"K1-2-u5-C5","difficulty":3,"kind":"error","stem":"친구가 「나는 훌라후프를 제일 잘 돌려서 칭찬을 받았다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"글에 없는 일이에요 — 포기하지 않고 노력해서 칭찬을 받았어요","correct":true,"mis_target":"K1-2-u5-X13"},{"t":"잘 정리했어요","mis":"K1-2-u5-X13"},{"t":"칭찬은 받지 않았어요","mis":"K1-2-u5-X13"}],"explanation":["「나」는 아직 잘 돌리지 못해요.","노력하는 모습을 칭찬받았어요.","169쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#21','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C7',3,'error','auto','친구가 독서 계단에 제목을 쓰자마자 모든 칸을 색칠했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":21,"concept":"K1-2-u5-C7","difficulty":3,"kind":"error","stem":"친구가 독서 계단에 제목을 쓰자마자 모든 칸을 색칠했어요. 무엇이 잘못되었나요?","options":[{"t":"다 읽은 책만 한 칸씩 색칠해요","correct":true,"mis_target":"K1-2-u5-X17"},{"t":"잘했어요","mis":"K1-2-u5-X17"},{"t":"색칠은 하지 않아요","mis":"K1-2-u5-X17"}],"explanation":["색칠은 다 읽었다는 표시예요.","한 칸씩 색칠해요.","172쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#22','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',3,'mc','auto','『국어』 174쪽 1번 (2) — 안내판을 보고 떠오른 생각이나 느낌으로 알맞은 것은?',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":22,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"『국어』 174쪽 1번 (2) — 안내판을 보고 떠오른 생각이나 느낌으로 알맞은 것은?","options":[{"t":"산에 떨어진 도토리와 밤을 주워 오지 말아야겠다","correct":true},{"t":"도토리는 동그랗게 생겼다","mis":"K1-2-u5-X15"},{"t":"안내판이 나무로 되어 있다","mis":"K1-2-u5-X15"}],"explanation":["안내판이 말하려는 까닭을 짐작했어요.","다람쥐도 겨울을 날 수 있어요.","174쪽 1번이에요."],"asset":{"type":"passage","lines":["도토리와 밤은 겨울철 야생 동물의 먹이입니다.","다람쥐에게 도토리를 돌려주세요!"],"title":"『국어』 174쪽 — 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#23','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C1',4,'sa','auto','「밤」의 첫 자음자 「ㅂ」을 「ㄹ」로 바꾸면 어떤 글자가 되나요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u5-C1","difficulty":4,"kind":"sa","stem":"「밤」의 첫 자음자 「ㅂ」을 「ㄹ」로 바꾸면 어떤 글자가 되나요?","answer":["람"],"explanation":["「ㄹ」+「ㅏ」+「ㅁ」은 「람」이에요.","174쪽 안내판의 「다람쥐」에 있어요.","174쪽 1번이에요."],"asset":{"type":"passage","lines":["도토리와 밤은 겨울철 야생 동물의 먹이입니다.","다람쥐에게 도토리를 돌려주세요!"],"title":"『국어』 174쪽 — 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#24','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',4,'essay','teacher','『국어』 174쪽 — 안내판을 읽고 떠오른 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"『국어』 174쪽 — 안내판을 읽고 떠오른 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 다람쥐가 겨울에 먹을 것이 없을까 봐 걱정되었어요. 산에서 도토리를 주워 오지 않겠어요. — 안내판 내용과 이어진 생각이면 맞아요.","scoring_points":["안내판 내용과 이어지는가","내 생각이나 느낌을 썼는가","문장이 자연스러운가"]},"explanation":["안내판이 무엇을 말하는지 먼저 생각해요.","떠오른 생각을 내 말로 써요.","174쪽 1번이에요."],"asset":{"type":"passage","lines":["도토리와 밤은 겨울철 야생 동물의 먹이입니다.","다람쥐에게 도토리를 돌려주세요!"],"title":"『국어』 174쪽 — 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#25','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',4,'essay','teacher','『국어』 175쪽 3번 — 「손」에서 한 자리만 바꾸어 뜻이 있는 낱말을 두 개 만들고, 바꾼 자리를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C3","difficulty":4,"kind":"essay","stem":"『국어』 175쪽 3번 — 「손」에서 한 자리만 바꾸어 뜻이 있는 낱말을 두 개 만들고, 바꾼 자리를 쓰세요.","answer_guide":{"answer":"예: 돈 — 첫 자음자 / 산 — 모음자 / 솜 — 받침 — 뜻이 있는 낱말 둘과 바꾼 자리가 맞으면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","한 자리만 바꾸었는가","바꾼 자리 이름을 바르게 썼는가"]},"explanation":["첫 자음자·모음자·받침 가운데 하나만 바꿔요.","뜻이 있는지 확인해요.","175쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#1','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C1',1,'mc','auto','『국어』 174쪽 — 「동」과 「돌」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 174쪽 — 「동」과 「돌」은 어느 자리가 다른가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㅇ」과 「ㄹ」이 달라요.","첫 자음자와 모음자는 같아요.","174쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#2','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',1,'mc','auto','「ㄷ」에 한 획을 더하면 어떤 자음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"「ㄷ」에 한 획을 더하면 어떤 자음자가 되나요?","options":[{"t":"ㅌ","correct":true},{"t":"ㅁ","mis":"K1-2-u5-X06"},{"t":"ㅅ","mis":"K1-2-u5-X06"}],"explanation":["「ㄷ」에 획을 더하면 「ㅌ」이에요.","소리가 더 세져요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#3','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',1,'mc','auto','한글을 만든 사람은 누구인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글을 만든 사람은 누구인가요?","options":[{"t":"세종 대왕","correct":true},{"t":"이순신 장군","mis":"K1-2-u5-X04"},{"t":"아무도 몰라요","mis":"K1-2-u5-X04"}],"explanation":["세종 대왕이 만들었어요.","누가 만들었는지 알려진 글자예요.","151쪽 4번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#4','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',1,'mc','auto','『국어』 175쪽 3번 — 「손」의 모음자만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 175쪽 3번 — 「손」의 모음자만 바꾼 낱말은?","options":[{"t":"산","correct":true},{"t":"돈","mis":"K1-2-u5-X01"},{"t":"솔","mis":"K1-2-u5-X01"}],"explanation":["「ㅗ」를 「ㅏ」로 바꾸면 「산」이에요.","「돈」은 첫 자음자, 「솔」은 받침을 바꿨어요.","175쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#5','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C8',1,'mc','auto','『국어』 176쪽 — 「연필 한 ( )」에 알맞은 말은?',ARRAY['K1-2-u5-X20']::text[],false,'{"seq":5,"concept":"K1-2-u5-C8","difficulty":1,"kind":"mc","stem":"『국어』 176쪽 — 「연필 한 ( )」에 알맞은 말은?","options":[{"t":"자루","correct":true},{"t":"장","mis":"K1-2-u5-X20"},{"t":"켤레","mis":"K1-2-u5-X20"}],"explanation":["연필은 「자루」로 세요.","연필 한 자루예요.","176쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#6','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C4',1,'mc','auto','「그래, 책이야!」에서 동키가 들고 있는 것은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"「그래, 책이야!」에서 동키가 들고 있는 것은?","options":[{"t":"노트북","correct":true},{"t":"책","mis":"K1-2-u5-X13"},{"t":"공","mis":"K1-2-u5-X13"}],"explanation":["동키는 노트북을 들고 있어요.","책은 몽키가 들고 있어요.","간추림 첫째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#7','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C5',1,'mc','auto','선생님은 「나」의 어떤 모습을 칭찬하셨나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":7,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"선생님은 「나」의 어떤 모습을 칭찬하셨나요?","options":[{"t":"포기하지 않고 노력하는 모습","correct":true},{"t":"훌라후프를 가장 잘 돌리는 모습","mis":"K1-2-u5-X13"},{"t":"조용히 앉아 있는 모습","mis":"K1-2-u5-X13"}],"explanation":["노력하는 모습이 기특하다고 하셨어요.","가장 잘 돌린 것은 아니에요.","169쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#8','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C7',1,'mc','auto','독서 계단은 언제 색칠하나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계단은 언제 색칠하나요?","options":[{"t":"그 책을 다 읽었을 때","correct":true},{"t":"책 제목을 썼을 때","mis":"K1-2-u5-X17"},{"t":"책을 빌려 왔을 때","mis":"K1-2-u5-X17"}],"explanation":["다 읽은 책의 계단을 색칠해요.","한 칸씩 올라가요.","172쪽이에요."],"asset":{"type":"scene","icon":"🪜📚","text":"독서 계단 — 맨 아래 칸부터 차례대로 읽고 다 읽으면 색칠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#9','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C1',2,'match','auto','두 글자에서 다른 자리를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C1","difficulty":2,"kind":"match","stem":"두 글자에서 다른 자리를 이어 보세요.","pairs":[{"l":"금 · 음","r":"첫 자음자"},{"l":"금 · 곰","r":"모음자"},{"l":"람 · 란","r":"받침"}],"mis":"K1-2-u5-X01","explanation":["금·음은 첫 자음자, 금·곰은 모음자예요.","람·란은 받침이 달라요.","세 자리로 나누어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#10','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',2,'match','auto','한글에 대한 물음과 답을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":2,"kind":"match","stem":"한글에 대한 물음과 답을 이어 보세요.","pairs":[{"l":"한글을 만든 사람","r":"세종 대왕"},{"l":"한글을 만든 때","r":"조선 시대"},{"l":"한글을 만든 까닭","r":"백성이 쉽게 읽고 쓰게 하려고"}],"mis":"K1-2-u5-X04","explanation":["누가·언제·왜가 알려져 있어요.","이것이 한글의 특별한 점이에요.","151쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#11','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',2,'mc','auto','「달」을 「발」로 바꿀 때 바꾼 자리는?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":11,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「달」을 「발」로 바꿀 때 바꾼 자리는?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["「ㄷ」이 「ㅂ」으로 바뀌었어요.","모음자와 받침은 그대로예요.","152쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#12','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C4',2,'mc','auto','「재미있는 책」에 들어가지 않는 것은?',ARRAY['K1-2-u5-X09']::text[],false,'{"seq":12,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「재미있는 책」에 들어가지 않는 것은?","options":[{"t":"제목만 보고 읽지 않은 책","correct":true},{"t":"감동적인 이야기가 담긴 책","mis":"K1-2-u5-X09"},{"t":"놀라운 이야기가 담긴 책","mis":"K1-2-u5-X09"}],"explanation":["감동·놀라움도 책의 재미예요.","읽지 않은 책은 재미를 알 수 없어요.","166쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#13','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C5',2,'match','auto','있었던 일과 글쓴이의 마음을 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"있었던 일과 글쓴이의 마음을 이어 보세요.","pairs":[{"l":"운동장에 나가자는 말을 들었을 때","r":"하기 싫은 마음"},{"l":"친구들이 잘 돌리는 것을 볼 때","r":"부러운 마음"},{"l":"선생님께 칭찬을 받았을 때","r":"뿌듯한 마음"}],"mis":"K1-2-u5-X14","explanation":["일이 달라지면 마음도 달라져요.","나라면 어땠을지 떠올려요.","170쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#14','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',2,'ox','auto','「좋았다.」라고만 말해도 생각이나 느낌을 구체적으로 말한 것이에요.',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":14,"concept":"K1-2-u5-C6","difficulty":2,"kind":"ox","stem":"「좋았다.」라고만 말해도 생각이나 느낌을 구체적으로 말한 것이에요.","answer":"X","reason_options":[{"t":"글의 어느 부분 때문에 그렇게 느꼈는지 함께 말해야 구체적이니까","correct":true},{"t":"짧게 말할수록 구체적이니까","mis":"K1-2-u5-X10"}],"mis":"K1-2-u5-X10","explanation":["어느 부분 때문인지 넣어 말해요.","「좋았다.」만으로는 알 수 없어요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#15','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C8',2,'match','auto','『국어』 176쪽 — 물건과 세는 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"K1-2-u5-C8","difficulty":2,"kind":"match","stem":"『국어』 176쪽 — 물건과 세는 말을 이어 보세요.","pairs":[{"l":"신발 한","r":"켤레"},{"l":"수박 한","r":"통"},{"l":"수저 한","r":"벌"}],"mis":"K1-2-u5-X20","explanation":["신발 한 켤레, 수박 한 통이에요.","수저 한 벌이에요.","176쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#16','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',2,'ox','auto','「ㅋ」은 「ㄱ」보다 소리가 약해요.',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":16,"concept":"K1-2-u5-C2","difficulty":2,"kind":"ox","stem":"「ㅋ」은 「ㄱ」보다 소리가 약해요.","answer":"X","reason_options":[{"t":"「ㄱ」에 획을 더한 「ㅋ」은 소리가 더 세니까","correct":true},{"t":"획을 더하면 소리가 약해지니까","mis":"K1-2-u5-X06"}],"mis":"K1-2-u5-X06","explanation":["획을 더하면 소리가 세져요.","「ㅋ」이 더 세요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#17','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C1',3,'error','auto','「람」과 「란」은 모음자가 다르다고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":17,"concept":"K1-2-u5-C1","difficulty":3,"kind":"error","stem":"「람」과 「란」은 모음자가 다르다고 했어요. 무엇이 잘못되었나요?","options":[{"t":"받침 「ㅁ」과 「ㄴ」이 달라요","correct":true,"mis_target":"K1-2-u5-X01"},{"t":"맞게 말했어요","mis":"K1-2-u5-X01"},{"t":"첫 자음자가 달라요","mis":"K1-2-u5-X01"}],"explanation":["모음자는 똑같이 「ㅏ」예요.","받침이 달라요.","149쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#18','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',3,'error','auto','친구가 「한글은 누가 만들었는지 아무도 몰라요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":18,"concept":"K1-2-u5-C2","difficulty":3,"kind":"error","stem":"친구가 「한글은 누가 만들었는지 아무도 몰라요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"한글은 누가, 언제, 왜 만들었는지 알려진 글자예요","correct":true,"mis_target":"K1-2-u5-X04"},{"t":"맞는 말이에요","mis":"K1-2-u5-X04"},{"t":"한글은 저절로 생겼어요","mis":"K1-2-u5-X04"}],"explanation":["세종 대왕이 만들었어요.","조선 시대에 백성을 위해 만들었어요.","151쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#19','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C4',3,'error','auto','재미있었던 부분을 다르게 고른 친구에게 「네가 틀렸어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X11']::text[],false,'{"seq":19,"concept":"K1-2-u5-C4","difficulty":3,"kind":"error","stem":"재미있었던 부분을 다르게 고른 친구에게 「네가 틀렸어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"재미있게 느낀 부분은 친구마다 다를 수 있어요","correct":true,"mis_target":"K1-2-u5-X11"},{"t":"맞게 말했어요","mis":"K1-2-u5-X11"},{"t":"모두 같은 부분을 골라야 해요","mis":"K1-2-u5-X11"}],"explanation":["사람마다 재미를 느끼는 곳이 달라요.","나누면 더 재미있어요.","166쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#20','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C5',3,'error','auto','「어휴.」라고 했을 때 글쓴이가 신났을 거라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":20,"concept":"K1-2-u5-C5","difficulty":3,"kind":"error","stem":"「어휴.」라고 했을 때 글쓴이가 신났을 거라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"훌라후프를 잘 못 돌려서 하기 싫은 마음이었어요","correct":true,"mis_target":"K1-2-u5-X14"},{"t":"맞게 짐작했어요","mis":"K1-2-u5-X14"},{"t":"글쓴이는 아무 마음도 없었어요","mis":"K1-2-u5-X14"}],"explanation":["신난 것은 친구들이에요.","「어휴.」에는 하기 싫은 마음이 담겨 있어요.","168쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#21','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C7',3,'error','auto','친구가 「제일 두꺼운 책을 첫 번째 계단에 쓸래.」라고 했어요. 무엇을 고치면 좋을까요?',ARRAY['K1-2-u5-X19','K1-2-u5-X17']::text[],false,'{"seq":21,"concept":"K1-2-u5-C7","difficulty":3,"kind":"error","stem":"친구가 「제일 두꺼운 책을 첫 번째 계단에 쓸래.」라고 했어요. 무엇을 고치면 좋을까요?","options":[{"t":"읽기 쉽고 흥미 있는 책을 첫 계단에 써요","correct":true,"mis_target":"K1-2-u5-X19"},{"t":"잘 정했어요","mis":"K1-2-u5-X19"},{"t":"가장 높은 계단에 써야 해요","mis":"K1-2-u5-X17"}],"explanation":["첫 계단에서 끝까지 읽는 경험이 중요해요.","흥미와 수준으로 골라요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#22','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',3,'mc','auto','안내판이 「다람쥐에게 도토리를 돌려주세요!」라고 한 까닭은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":22,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"안내판이 「다람쥐에게 도토리를 돌려주세요!」라고 한 까닭은?","options":[{"t":"도토리와 밤은 겨울철 야생 동물의 먹이라서","correct":true},{"t":"도토리가 맛이 없어서","mis":"K1-2-u5-X13"},{"t":"다람쥐가 도토리를 팔아서","mis":"K1-2-u5-X13"}],"explanation":["안내판 첫째 줄에 까닭이 있어요.","도토리와 밤은 동물의 먹이예요.","174쪽 1번이에요."],"asset":{"type":"passage","lines":["도토리와 밤은 겨울철 야생 동물의 먹이입니다.","다람쥐에게 도토리를 돌려주세요!"],"title":"『국어』 174쪽 — 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#23','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',4,'sa','auto','「ㅈ」에 한 획을 더하면 어떤 자음자가 되나요? 자음자 하나를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u5-C2","difficulty":4,"kind":"sa","stem":"「ㅈ」에 한 획을 더하면 어떤 자음자가 되나요? 자음자 하나를 쓰세요.","answer":["ㅊ"],"explanation":["「ㅈ」에 획을 더하면 「ㅊ」이에요.","소리가 더 세져요.","150쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#24','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',4,'essay','teacher','「너무너무 어려운 훌라후프 돌리기」에서 글쓴이가 한 일에 대한 생각이나 느낌을 글의 어느 부분 때문인지 넣어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「너무너무 어려운 훌라후프 돌리기」에서 글쓴이가 한 일에 대한 생각이나 느낌을 글의 어느 부분 때문인지 넣어 쓰세요.","answer_guide":{"answer":"예: 선생님께 칭찬을 받고도 더 잘하고 싶다고 한 부분을 읽고, 글쓴이를 응원해 주고 싶었어. — 글의 부분과 내 생각이 함께 있으면 맞아요.","scoring_points":["글의 어느 부분인지 썼는가","내 생각이나 느낌을 썼는가","글쓴이의 말을 그대로 옮기지 않았는가"]},"explanation":["글쓴이가 한 일을 짚어요.","그 부분을 읽고 든 내 마음을 써요.","171쪽 3번이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#25','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',4,'essay','teacher','「공」에서 한 자리만 바꾸어 뜻이 있는 낱말을 두 개 만들고, 바꾼 자리를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C3","difficulty":4,"kind":"essay","stem":"「공」에서 한 자리만 바꾸어 뜻이 있는 낱말을 두 개 만들고, 바꾼 자리를 쓰세요.","answer_guide":{"answer":"예: 콩 — 첫 자음자 / 강 — 모음자 / 곰 — 받침 — 뜻이 있는 낱말 둘과 바꾼 자리가 맞으면 맞아요.","scoring_points":["뜻이 있는 낱말을 두 개 만들었는가","한 자리만 바꾸었는가","바꾼 자리 이름을 바르게 썼는가"]},"explanation":["한 자리만 바꿔요.","뜻이 없는 글자는 빼요.","153쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#1','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C1',1,'mc','auto','「금」과 「음」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「금」과 「음」은 어느 자리가 다른가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["「ㄱ」과 「ㅇ」이 달라요.","모음자와 받침은 같아요.","149쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#2','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',1,'mc','auto','「ㅈ」에 한 획을 더하면 어떤 자음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"「ㅈ」에 한 획을 더하면 어떤 자음자가 되나요?","options":[{"t":"ㅊ","correct":true},{"t":"ㅅ","mis":"K1-2-u5-X06"},{"t":"ㅎ","mis":"K1-2-u5-X06"}],"explanation":["「ㅈ」에 획을 더하면 「ㅊ」이에요.","소리가 더 세져요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#3','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',1,'mc','auto','한글이 만들어지기 전에 빌려 쓰던 글자는?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글이 만들어지기 전에 빌려 쓰던 글자는?","options":[{"t":"한자","correct":true},{"t":"영어 알파벳","mis":"K1-2-u5-X04"},{"t":"그림 글자","mis":"K1-2-u5-X04"}],"explanation":["중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려웠어요.","150쪽 2번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#4','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C3',1,'mc','auto','『국어』 175쪽 3번 — 「손」의 받침만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 175쪽 3번 — 「손」의 받침만 바꾼 낱말은?","options":[{"t":"솜","correct":true},{"t":"산","mis":"K1-2-u5-X01"},{"t":"돈","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㄴ」을 「ㅁ」으로 바꾸면 「솜」이에요.","「산」과 「돈」은 다른 자리를 바꿨어요.","175쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#5','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C8',1,'mc','auto','『국어』 176쪽 — 「차 한 ( )」에 알맞은 말은?',ARRAY['K1-2-u5-X20']::text[],false,'{"seq":5,"concept":"K1-2-u5-C8","difficulty":1,"kind":"mc","stem":"『국어』 176쪽 — 「차 한 ( )」에 알맞은 말은?","options":[{"t":"대","correct":true},{"t":"통","mis":"K1-2-u5-X20"},{"t":"벌","mis":"K1-2-u5-X20"}],"explanation":["차는 「대」로 세요.","차 한 대예요.","176쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#6','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',1,'mc','auto','책을 건네받은 동키는 어떻게 되었나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"책을 건네받은 동키는 어떻게 되었나요?","options":[{"t":"시간 가는 줄 모르고 책에 푹 빠졌어요","correct":true},{"t":"책을 바로 돌려주었어요","mis":"K1-2-u5-X13"},{"t":"노트북만 보았어요","mis":"K1-2-u5-X13"}],"explanation":["동키는 책에 푹 빠졌어요.","돌려 달라고 해도 돌려주지 않았어요.","간추림 넷째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#7','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C5',1,'mc','auto','선생님의 말씀에 친구들은 뭐라고 했나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":7,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"선생님의 말씀에 친구들은 뭐라고 했나요?","options":[{"t":"「우아!」","correct":true},{"t":"「어휴.」","mis":"K1-2-u5-X13"},{"t":"「싫어요.」","mis":"K1-2-u5-X13"}],"explanation":["친구들은 「우아!」 하고 소리를 질렀어요.","「어휴.」는 「나」가 한 말이에요.","168쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#8','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C7',1,'mc','auto','독서 계단의 책은 어떻게 읽나요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계단의 책은 어떻게 읽나요?","options":[{"t":"한 권을 처음부터 끝까지 온전히 읽어요","correct":true},{"t":"앞부분만 훑어 읽어요","mis":"K1-2-u5-X19"},{"t":"재미있는 쪽만 뛰어 읽어요","mis":"K1-2-u5-X19"}],"explanation":["한 권을 끝까지 읽어요.","그다음 계단으로 올라가요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#9','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C1',2,'match','auto','『국어』 174쪽 — 두 글자에서 다른 자리를 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C1","difficulty":2,"kind":"match","stem":"『국어』 174쪽 — 두 글자에서 다른 자리를 이어 보세요.","pairs":[{"l":"밤 · 람","r":"첫 자음자"},{"l":"달 · 덜","r":"모음자"},{"l":"동 · 돌","r":"받침"}],"mis":"K1-2-u5-X01","explanation":["밤·람은 첫 자음자, 달·덜은 모음자예요.","동·돌은 받침이 달라요.","174쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#10','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',2,'mc','auto','자음자에 획을 더하면 소리는 어떻게 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"자음자에 획을 더하면 소리는 어떻게 되나요?","options":[{"t":"더 세져요","correct":true},{"t":"더 약해져요","mis":"K1-2-u5-X06"},{"t":"똑같아요","mis":"K1-2-u5-X06"}],"explanation":["「ㄱ」보다 「ㅋ」이 세요.","소리 내어 견주어 봐요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#11','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C3',2,'mc','auto','「감」의 받침만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":11,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「감」의 받침만 바꾼 낱말은?","options":[{"t":"갓","correct":true},{"t":"밤","mis":"K1-2-u5-X01"},{"t":"곰","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㅁ」을 「ㅅ」으로 바꾸면 「갓」이에요.","「밤」은 첫 자음자, 「곰」은 모음자를 바꿨어요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#12','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',2,'mc','auto','동키가 책을 충전해 놓겠다고 한 까닭은?',ARRAY['K1-2-u5-X13','K1-2-u5-X09']::text[],false,'{"seq":12,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"동키가 책을 충전해 놓겠다고 한 까닭은?","options":[{"t":"아직 책을 노트북처럼 생각해서","correct":true},{"t":"책에도 충전기가 꼭 필요해서","mis":"K1-2-u5-X13"},{"t":"책이 지루해서","mis":"K1-2-u5-X09"}],"explanation":["동키는 책을 노트북처럼 생각했어요.","그래서 웃음이 나는 장면이에요.","간추림 마지막 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#13','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C5',2,'mc','auto','「나」가 훌라후프를 잘 돌리고 싶어서 한 일은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":13,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「나」가 훌라후프를 잘 돌리고 싶어서 한 일은?","options":[{"t":"훌라후프가 있다고 생각하며 허리를 이리저리 움직였어요","correct":true},{"t":"훌라후프를 몰래 숨겼어요","mis":"K1-2-u5-X13"},{"t":"교실로 들어가 버렸어요","mis":"K1-2-u5-X13"}],"explanation":["훌라후프 없이도 연습했어요.","글에 없는 일은 고르지 않아요.","169쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#14','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C6',2,'mc','auto','글쓴이와 비슷한 경험으로 알맞은 것은?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":14,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"글쓴이와 비슷한 경험으로 알맞은 것은?","options":[{"t":"다른 친구들은 잘하는데 나만 받아쓰기를 틀려서 속상했던 일","correct":true},{"t":"가족과 놀이공원에 간 일","mis":"K1-2-u5-X16"},{"t":"가게에서 훌라후프를 산 일","mis":"K1-2-u5-X16"}],"explanation":["마음이 비슷한 경험이에요.","물건이 같아도 마음이 다르면 비슷하지 않아요.","지도서 228쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#15','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C8',2,'match','auto','물건과 세는 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"K1-2-u5-C8","difficulty":2,"kind":"match","stem":"물건과 세는 말을 이어 보세요.","pairs":[{"l":"배추 한","r":"포기"},{"l":"배 한","r":"척"},{"l":"집 한","r":"채"}],"mis":"K1-2-u5-X20","explanation":["배추 한 포기, 배 한 척이에요.","집 한 채예요.","176쪽 더 알아보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#16','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',2,'ox','auto','한글은 누가, 언제, 왜 만들었는지 알려진 글자예요.',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":16,"concept":"K1-2-u5-C2","difficulty":2,"kind":"ox","stem":"한글은 누가, 언제, 왜 만들었는지 알려진 글자예요.","answer":"O","reason_options":[{"t":"세종 대왕이 조선 시대에 백성을 위해 만들었으니까","correct":true},{"t":"글자는 모두 저절로 생겼으니까","mis":"K1-2-u5-X04"}],"mis":"K1-2-u5-X04","explanation":["세종 대왕이 백성을 위해 만들었어요.","조선 시대에 만들었어요.","151쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#17','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C3',3,'error','auto','친구가 「달」에서 「별」을 만들고 「한 자리만 바꾸었어요.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X02','K1-2-u5-X01']::text[],false,'{"seq":17,"concept":"K1-2-u5-C3","difficulty":3,"kind":"error","stem":"친구가 「달」에서 「별」을 만들고 「한 자리만 바꾸었어요.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"첫 자음자와 모음자, 두 자리를 바꾸었어요","correct":true,"mis_target":"K1-2-u5-X02"},{"t":"맞게 말했어요","mis":"K1-2-u5-X02"},{"t":"받침을 바꾸었어요","mis":"K1-2-u5-X01"}],"explanation":["두 자리가 바뀌었어요.","한 자리씩 바꾸면 달 → 발 → 별이에요.","152~153쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#18','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',3,'mc','auto','「ㅗ」의 방향을 달리해서 만들 수 없는 모음자는?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":18,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"「ㅗ」의 방향을 달리해서 만들 수 없는 모음자는?","options":[{"t":"ㅣ","correct":true},{"t":"ㅏ","mis":"K1-2-u5-X06"},{"t":"ㅓ","mis":"K1-2-u5-X06"}],"explanation":["「ㅗ」를 돌리면 ㅏ·ㅜ·ㅓ예요.","「ㅣ」는 돌려서 만들 수 없어요.","150쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#19','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',3,'error','auto','「그래, 책이야!」를 읽고 「재미있었다.」라고만 말했어요. 무엇이 부족한가요?',ARRAY['K1-2-u5-X10','K1-2-u5-X08']::text[],false,'{"seq":19,"concept":"K1-2-u5-C4","difficulty":3,"kind":"error","stem":"「그래, 책이야!」를 읽고 「재미있었다.」라고만 말했어요. 무엇이 부족한가요?","options":[{"t":"어느 부분이 왜 재미있었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u5-X10"},{"t":"잘 말했어요","mis":"K1-2-u5-X10"},{"t":"책의 쪽수를 말해야 해요","mis":"K1-2-u5-X08"}],"explanation":["어느 장면이 왜 재미있었는지 말해요.","그래야 친구도 함께 느껴요.","166쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#20','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C6',3,'error','auto','생각을 말해 보라고 했더니 글의 마지막 문장을 그대로 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":20,"concept":"K1-2-u5-C6","difficulty":3,"kind":"error","stem":"생각을 말해 보라고 했더니 글의 마지막 문장을 그대로 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"글쓴이의 말을 그대로 옮겼어요 — 그 부분을 읽고 내 마음이 어땠는지 말해요","correct":true,"mis_target":"K1-2-u5-X15"},{"t":"잘 말했어요","mis":"K1-2-u5-X15"},{"t":"더 크게 읽어야 해요","mis":"K1-2-u5-X15"}],"explanation":["글에 있는 문장은 글쓴이의 생각이에요.","내 생각을 내 말로 말해요.","지도서 238쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#21','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C7',3,'error','auto','친구가 책 여러 권의 앞부분만 넘겨 보고 계단을 모두 색칠했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X19','K1-2-u5-X17']::text[],false,'{"seq":21,"concept":"K1-2-u5-C7","difficulty":3,"kind":"error","stem":"친구가 책 여러 권의 앞부분만 넘겨 보고 계단을 모두 색칠했어요. 무엇이 잘못되었나요?","options":[{"t":"한 권을 끝까지 읽고 나서 색칠해요","correct":true,"mis_target":"K1-2-u5-X19"},{"t":"잘했어요","mis":"K1-2-u5-X19"},{"t":"색칠을 더 진하게 해야 해요","mis":"K1-2-u5-X17"}],"explanation":["훑어보기만 하면 다 읽은 것이 아니에요.","한 권을 온전히 읽어요.","지도서 230쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#22','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C8',3,'error','auto','친구가 「신발 한 대」라고 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X20']::text[],false,'{"seq":22,"concept":"K1-2-u5-C8","difficulty":3,"kind":"error","stem":"친구가 「신발 한 대」라고 말했어요. 무엇이 잘못되었나요?","options":[{"t":"신발은 「켤레」로 세요 — 「신발 한 켤레」","correct":true,"mis_target":"K1-2-u5-X20"},{"t":"바르게 말했어요","mis":"K1-2-u5-X20"},{"t":"「신발 한 장」이라고 해야 해요","mis":"K1-2-u5-X20"}],"explanation":["「대」는 차를 셀 때 써요.","신발은 두 짝을 「켤레」로 세요.","176쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#23','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C8',4,'sa','auto','『국어』 176쪽 — 「수박 한 ( )」의 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u5-C8","difficulty":4,"kind":"sa","stem":"『국어』 176쪽 — 「수박 한 ( )」의 빈칸에 알맞은 말을 쓰세요.","answer":["통"],"explanation":["수박은 「통」으로 세요.","수박 한 통이에요.","176쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#24','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',4,'essay','teacher','「저는 책을 ○○(이)라고 생각합니다. 왜냐하면 ~ 때문입니다.」 틀에 맞추어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"「저는 책을 ○○(이)라고 생각합니다. 왜냐하면 ~ 때문입니다.」 틀에 맞추어 쓰세요.","answer_guide":{"answer":"예: 저는 책을 비행기라고 생각합니다. 왜냐하면 책은 나를 어디로든 데려다줄 수 있기 때문입니다. — 비유와 까닭이 있으면 맞아요.","scoring_points":["책을 무엇에 빗대었는가","까닭을 썼는가","틀에 맞게 썼는가"]},"explanation":["책과 닮은 것을 떠올려요.","까닭을 함께 써요.","167쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#25','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C7',4,'essay','teacher','독서 계단의 첫 번째 계단에 쓸 책을 정하고, 그 책을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C7","difficulty":4,"kind":"essay","stem":"독서 계단의 첫 번째 계단에 쓸 책을 정하고, 그 책을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「요술 항아리」 — 읽기 쉽고, 항아리에서 무엇이 나올지 궁금해서요. — 책 제목과 까닭이 있으면 맞아요.","scoring_points":["책 제목을 썼는가","흥미나 읽기 수준과 관련된 까닭인가","문장이 자연스러운가"]},"explanation":["읽기 쉽고 흥미 있는 책을 골라요.","고른 까닭을 써요.","172쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#1','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C1',1,'mc','auto','「람」과 「란」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「람」과 「란」은 어느 자리가 다른가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㅁ」과 「ㄴ」이 달라요.","첫 자음자와 모음자는 같아요.","149쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#2','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',1,'mc','auto','「ㅗ」를 거꾸로 뒤집으면 어떤 모음자가 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"「ㅗ」를 거꾸로 뒤집으면 어떤 모음자가 되나요?","options":[{"t":"ㅜ","correct":true},{"t":"ㅏ","mis":"K1-2-u5-X06"},{"t":"ㅡ","mis":"K1-2-u5-X06"}],"explanation":["「ㅗ」의 방향을 아래로 바꾸면 「ㅜ」예요.","모음자는 방향을 달리해 만들어요.","150쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#3','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',1,'mc','auto','한글을 만든 때는 언제인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글을 만든 때는 언제인가요?","options":[{"t":"조선 시대","correct":true},{"t":"아주 먼 옛날 저절로","mis":"K1-2-u5-X04"},{"t":"지난해","mis":"K1-2-u5-X04"}],"explanation":["한글은 조선 시대에 만들었어요.","언제 만들었는지 알려진 글자예요.","151쪽 4번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#4','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',1,'mc','auto','「물」의 첫 자음자만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「물」의 첫 자음자만 바꾼 낱말은?","options":[{"t":"굴","correct":true},{"t":"말","mis":"K1-2-u5-X01"},{"t":"문","mis":"K1-2-u5-X01"}],"explanation":["「ㅁ」을 「ㄱ」으로 바꾸면 「굴」이에요.","「말」은 모음자, 「문」은 받침을 바꿨어요.","175쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#5','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C8',1,'mc','auto','『국어』 176쪽 — 「신발 한 ( )」에 알맞은 말은?',ARRAY['K1-2-u5-X20']::text[],false,'{"seq":5,"concept":"K1-2-u5-C8","difficulty":1,"kind":"mc","stem":"『국어』 176쪽 — 「신발 한 ( )」에 알맞은 말은?","options":[{"t":"켤레","correct":true},{"t":"대","mis":"K1-2-u5-X20"},{"t":"통","mis":"K1-2-u5-X20"}],"explanation":["신발은 두 짝을 「켤레」로 세요.","신발 한 켤레예요.","176쪽 기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#6','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',1,'mc','auto','몽키는 책을 어떻게 읽는 것이라고 알려 주었나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"몽키는 책을 어떻게 읽는 것이라고 알려 주었나요?","options":[{"t":"한 장씩 넘기며 읽어요","correct":true},{"t":"화면을 눌러 넘겨요","mis":"K1-2-u5-X13"},{"t":"충전해서 읽어요","mis":"K1-2-u5-X13"}],"explanation":["책은 한 장씩 넘기며 읽어요.","화면을 누르는 것은 노트북이에요.","간추림 셋째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#7','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C5',1,'mc','auto','「나」가 훌라후프를 돌리면 어떻게 되나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":7,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「나」가 훌라후프를 돌리면 어떻게 되나요?","options":[{"t":"금방 뚝 떨어져요","correct":true},{"t":"오래오래 잘 돌아가요","mis":"K1-2-u5-X13"},{"t":"하늘로 날아가요","mis":"K1-2-u5-X13"}],"explanation":["「나」가 하면 금방 떨어져요.","그래서 잘 돌리고 싶었어요.","168쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#8','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C7',1,'mc','auto','책 보물 찾기에서 쪽지의 질문에 답하려면 어떻게 해야 하나요?',ARRAY['K1-2-u5-X18']::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"책 보물 찾기에서 쪽지의 질문에 답하려면 어떻게 해야 하나요?","options":[{"t":"그 책을 읽어야 해요","correct":true},{"t":"쪽지를 많이 모아야 해요","mis":"K1-2-u5-X18"},{"t":"제일 빨리 달려야 해요","mis":"K1-2-u5-X18"}],"explanation":["쪽지의 답은 책 속에 있어요.","진짜 보물은 책을 읽는 거예요.","173쪽이에요."],"asset":{"type":"passage","lines":["선생님이 학급 문고의 책 사이에 보물 쪽지를 숨겨 둬요.","「책 보물 찾기 시작!」 하면 쪽지를 찾아요. 한 사람이 두 개까지만 찾아요.","쪽지에 쓰인 질문의 답을 책을 읽고 써서 선생님께 내요.","선생님이 답을 확인하면 쪽지를 작은 선물로 바꿔 줘요."],"title":"『국어』 173쪽 — 책 보물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#9','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',2,'match','auto','「감」을 바꾸어 만든 낱말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":2,"kind":"match","stem":"「감」을 바꾸어 만든 낱말을 이어 보세요.","pairs":[{"l":"첫 자음자만 바꾸기","r":"밤"},{"l":"모음자만 바꾸기","r":"곰"},{"l":"받침만 바꾸기","r":"갓"}],"mis":"K1-2-u5-X01","explanation":["감 → 밤 · 곰 · 갓이에요.","바꾼 자리에 따라 다른 낱말이 돼요.","153쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#10','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',2,'mc','auto','한자로만 글을 썼을 때 어떤 문제가 있었나요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"한자로만 글을 썼을 때 어떤 문제가 있었나요?","options":[{"t":"배우기 어려워서 많은 백성이 글을 읽지 못했어요","correct":true},{"t":"글자가 너무 쉬워서 재미가 없었어요","mis":"K1-2-u5-X05"},{"t":"누구나 글을 잘 읽었어요","mis":"K1-2-u5-X05"}],"explanation":["한자는 배우기 어려웠어요.","그래서 한글을 만들었어요.","151쪽 3번이에요."],"asset":{"type":"passage","lines":["옛날에는 우리 글자가 없어서 중국의 글자인 한자를 빌려 썼어요.","한자는 배우기 어려워서 많은 백성이 글을 읽지 못했어요.","세종 대왕은 이것을 안타깝게 여겨,","백성이 쉽게 읽고 쓸 수 있는 글자를 만들었어요.","한글은 조선 시대에 만들어 널리 알렸어요."],"title":"『국어』 150쪽 — 한글을 만든 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#11','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',2,'mc','auto','「물」의 받침만 바꾼 낱말은?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":11,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「물」의 받침만 바꾼 낱말은?","options":[{"t":"문","correct":true},{"t":"굴","mis":"K1-2-u5-X01"},{"t":"말","mis":"K1-2-u5-X01"}],"explanation":["받침 「ㄹ」을 「ㄴ」으로 바꾸면 「문」이에요.","「굴」은 첫 자음자, 「말」은 모음자를 바꿨어요.","175쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#12','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',2,'mc','auto','동키가 책을 돌려주지 않은 까닭은?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":12,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"동키가 책을 돌려주지 않은 까닭은?","options":[{"t":"책에 흥미를 느껴 더 읽고 싶었기 때문이에요","correct":true},{"t":"몽키와 싸웠기 때문이에요","mis":"K1-2-u5-X13"},{"t":"책의 배터리가 다 닳았기 때문이에요","mis":"K1-2-u5-X13"}],"explanation":["책이 재미있어서 더 읽고 싶었어요.","싸운 일은 없어요.","166쪽이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#13','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C5',2,'mc','auto','칭찬을 받은 뒤 「나」의 마음은?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":13,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"칭찬을 받은 뒤 「나」의 마음은?","options":[{"t":"기분이 좋았지만 다음에는 더 잘 돌리고 싶어요","correct":true},{"t":"기분이 나빠서 그만두고 싶어요","mis":"K1-2-u5-X14"},{"t":"아무 마음도 들지 않아요","mis":"K1-2-u5-X14"}],"explanation":["칭찬을 받아 기분이 좋았어요.","그래도 더 잘하고 싶어요.","169쪽이에요."],"asset":{"type":"passage","lines":["「자, 이제 운동장에 나가 볼까요?」","선생님의 말씀에 친구들은 모두 「우아!」 하고 소리를 질렀다.","나만 「어휴.」라고 했다. 왜냐하면 훌라후프로 운동하는 시간이기 때문이다.","친구들은 훌라후프가 떨어지지 않게 잘 돌린다.","그런데 내가 하면 훌라후프가 금방 뚝 떨어진다.","친구들처럼 잘 돌리고 싶어서 나는 훌라후프가 있다고 생각하면서 허리를 이리저리 움직였다.","선생님은 포기하지 않고 노력하는 모습이 기특하다고 칭찬해 주셨다.","칭찬을 받아서 기분이 좋았지만 다음에는 친구들처럼 훌라후프를 잘 돌리면 좋겠다."],"title":"『국어』 168~169쪽 — 너무너무 어려운 훌라후프 돌리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#14','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C6',2,'mc','auto','생각이나 느낌을 구체적으로 나타낸 말은?',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":14,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"생각이나 느낌을 구체적으로 나타낸 말은?","options":[{"t":"혼자만 「어휴.」라고 했을 때 안타까웠어","correct":true},{"t":"좋았다.","mis":"K1-2-u5-X10"},{"t":"재미있었다.","mis":"K1-2-u5-X10"}],"explanation":["글의 어느 부분 때문인지 드러나요.","한마디로 끝난 말은 구체적이지 않아요.","171쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#15','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C8',2,'match','auto','물건과 세는 말을 이어 보세요.','{}'::text[],false,'{"seq":15,"concept":"K1-2-u5-C8","difficulty":2,"kind":"match","stem":"물건과 세는 말을 이어 보세요.","pairs":[{"l":"쌀 한","r":"톨"},{"l":"두부 한","r":"모"},{"l":"옷 한","r":"벌"}],"mis":"K1-2-u5-X20","explanation":["쌀 한 톨, 두부 한 모예요.","옷 한 벌이에요.","176쪽 더 알아보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#16','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',2,'ox','auto','「곰」의 받침을 바꾼 「곺」도 뜻이 있는 낱말이에요.',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":16,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"「곰」의 받침을 바꾼 「곺」도 뜻이 있는 낱말이에요.","answer":"X","reason_options":[{"t":"「곺」은 소리만 나고 뜻이 없는 글자니까","correct":true},{"t":"글자를 바꾸면 모두 낱말이 되니까","mis":"K1-2-u5-X07"}],"mis":"K1-2-u5-X07","explanation":["뜻이 없는 글자는 낱말이 아니에요.","「공」, 「곳」처럼 뜻이 있는 낱말을 만들어요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#17','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',3,'error','auto','친구가 「곰」의 받침을 바꾸어 「곺」을 만들었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X07','K1-2-u5-X01']::text[],false,'{"seq":17,"concept":"K1-2-u5-C3","difficulty":3,"kind":"error","stem":"친구가 「곰」의 받침을 바꾸어 「곺」을 만들었어요. 무엇이 잘못되었나요?","options":[{"t":"「곺」은 뜻이 없는 글자예요 — 「공」, 「곳」처럼 뜻이 있는 낱말을 만들어요","correct":true,"mis_target":"K1-2-u5-X07"},{"t":"잘 만들었어요","mis":"K1-2-u5-X07"},{"t":"받침은 바꿀 수 없어요","mis":"K1-2-u5-X01"}],"explanation":["뜻이 없으면 낱말이 아니에요.","뜻이 있는 낱말만 만들어요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#18','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',3,'mc','auto','한글은 백성의 삶을 어떻게 바꾸어 놓았나요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":18,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"한글은 백성의 삶을 어떻게 바꾸어 놓았나요?","options":[{"t":"글을 읽고 쓸 수 있게 되어 편리해졌어요","correct":true},{"t":"글을 더 읽기 어려워졌어요","mis":"K1-2-u5-X05"},{"t":"아무것도 달라지지 않았어요","mis":"K1-2-u5-X05"}],"explanation":["백성도 글을 읽고 쓰게 되었어요.","생활이 편리해졌어요.","151쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#19','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',3,'mc','auto','동키에게 책을 추천할 때 함께 말하면 좋은 것은?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":19,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"동키에게 책을 추천할 때 함께 말하면 좋은 것은?","options":[{"t":"책 제목과 그 책을 고른 까닭","correct":true},{"t":"책의 값","mis":"K1-2-u5-X08"},{"t":"책의 무게","mis":"K1-2-u5-X08"}],"explanation":["제목과 고른 까닭을 말해요.","값이나 무게로는 재미를 알 수 없어요.","167쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#20','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C6',3,'error','auto','친구가 「나는 훌라후프를 돌린 적이 없으니 비슷한 경험이 없어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":20,"concept":"K1-2-u5-C6","difficulty":3,"kind":"error","stem":"친구가 「나는 훌라후프를 돌린 적이 없으니 비슷한 경험이 없어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"하는 일이 같지 않아도 마음이 비슷하면 비슷한 경험이에요","correct":true,"mis_target":"K1-2-u5-X16"},{"t":"맞는 말이에요","mis":"K1-2-u5-X16"},{"t":"훌라후프를 사서 해 봐야 해요","mis":"K1-2-u5-X16"}],"explanation":["나만 못해서 속상했던 마음이 닮았으면 돼요.","줄넘기·받아쓰기도 비슷한 경험이에요.","지도서 228쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#21','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C7',3,'ox','auto','책 보물 찾기에서는 보물 쪽지를 많이 찾을수록 좋아요.',ARRAY['K1-2-u5-X18']::text[],false,'{"seq":21,"concept":"K1-2-u5-C7","difficulty":3,"kind":"ox","stem":"책 보물 찾기에서는 보물 쪽지를 많이 찾을수록 좋아요.","answer":"X","reason_options":[{"t":"한 사람이 두 개까지만 찾고 쪽지의 질문에 답하려고 책을 읽는 활동이니까","correct":true},{"t":"쪽지를 많이 모은 사람이 이기는 놀이니까","mis":"K1-2-u5-X18"}],"mis":"K1-2-u5-X18","explanation":["두 개까지만 찾아요.","답을 쓰려면 책을 읽어야 해요.","173쪽이에요."],"asset":{"type":"passage","lines":["선생님이 학급 문고의 책 사이에 보물 쪽지를 숨겨 둬요.","「책 보물 찾기 시작!」 하면 쪽지를 찾아요. 한 사람이 두 개까지만 찾아요.","쪽지에 쓰인 질문의 답을 책을 읽고 써서 선생님께 내요.","선생님이 답을 확인하면 쪽지를 작은 선물로 바꿔 줘요."],"title":"『국어』 173쪽 — 책 보물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#22','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C8',3,'error','auto','친구가 「배추 한 장」이라고 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u5-X20']::text[],false,'{"seq":22,"concept":"K1-2-u5-C8","difficulty":3,"kind":"error","stem":"친구가 「배추 한 장」이라고 말했어요. 무엇이 잘못되었나요?","options":[{"t":"배추는 「포기」로 세요 — 「배추 한 포기」","correct":true,"mis_target":"K1-2-u5-X20"},{"t":"바르게 말했어요","mis":"K1-2-u5-X20"},{"t":"「배추 한 통」이라고 해야 해요","mis":"K1-2-u5-X20"}],"explanation":["「장」은 종이를 셀 때 써요.","배추는 「포기」로 세요.","176쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#23','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',4,'sa','auto','「그래, 책이야!」에서 동키가 들고 있던 전자 기기는 무엇인가요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u5-C4","difficulty":4,"kind":"sa","stem":"「그래, 책이야!」에서 동키가 들고 있던 전자 기기는 무엇인가요?","answer":["노트북"],"explanation":["동키는 노트북을 들고 있었어요.","몽키는 종이책이었어요.","간추림 첫째 줄이에요."],"asset":{"type":"passage","lines":["동키는 노트북을, 몽키는 종이책을 들고 마주 앉아 있어요.","동키는 책으로 게임을 하거나 메일을 보낼 수 있는지 자꾸 물어요.","몽키는 책은 한 장씩 넘기며 읽는 것이라고 알려 줘요.","책을 건네받은 동키는 시간 가는 줄 모르고 책에 푹 빠져요.","몽키가 책을 돌려 달라고 해도 동키는 돌려주지 않아요.","동키는 다 읽으면 책을 충전해 놓겠다고 해요."],"title":"「그래, 책이야!」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#24','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',4,'essay','teacher','한글이 있어 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C2","difficulty":4,"kind":"essay","stem":"한글이 있어 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 내 생각을 자유롭게 글로 쓸 수 있다. / 멀리 있는 사람에게 편지를 쓸 수 있다. — 두 가지면 맞아요.","scoring_points":["좋은 점을 두 가지 썼는가","한글 덕분에 할 수 있는 일인가","문장이 자연스러운가"]},"explanation":["한글 덕분에 할 수 있는 일을 떠올려요.","책 읽기·편지 쓰기도 있어요.","151쪽 5번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#25','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C7',4,'essay','teacher','우리 반에서 하고 싶은 책 활동을 하나 정하고, 하고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C7","difficulty":4,"kind":"essay","stem":"우리 반에서 하고 싶은 책 활동을 하나 정하고, 하고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 책 보물 찾기 — 쪽지의 질문에 답하려고 책을 읽으면 재미있을 것 같아서요. — 활동과 까닭이 있으면 맞아요.","scoring_points":["책 활동을 하나 정했는가","하고 싶은 까닭을 썼는가","책을 읽는 일과 이어지는가"]},"explanation":["책 보물 찾기, 책 카페 놀이 가운데 골라도 돼요.","까닭을 함께 써요.","173쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
